// Üretilen dosya: tool/ozgun/uret.py. Coğrafya · Toprak tipleri, kayaç döngüsü ve karstik-buzul-rüzgâr-kıyı yer şekilleri (çernozyom, terra rossa, lapya, polye, obruk, falez, tombolo, lagün, fiyort, moren) (orta).
const ozGeography17Orta = <(String, String, List<String>, String)>[
  ('Kapadokya yöresinde peri bacalarının oluşumunda üst kısımdaki şapka ile alt kısımdaki gövdeyi oluşturan kayaç ikilisi aşağıdakilerden hangisidir?', 'Bazalt - Volkan tüfü', ['Granit - Kalker tabakası', 'Mermer - Kil taşı kütlesi', 'Kuvarsit - Jips çökelleri'], 'Peri bacalarında aşınmaya dirençli bazalt (veya andezit) üstte şapkayı, kolay aşınan volkan tüfü ise alttaki gövdeyi oluşturur.'),
  ('Bir arazide yapılan jeolojik kazıda tabakalı yapı gösteren ve içinde deniz kabuklularına ait fosiller barındıran kayaçların üzerinde masif bazalt örtüsü saptanmıştır. Bu durum aşağıdakilerden hangisini kanıtlar?', 'Denizel tortullanmadan sonra volkanik faaliyet yaşandığını', ['Bölgenin sürekli karasal çöl iklimi etkisinde kaldığını', 'Bazaltların derinlik metamorfizmasıyla oluştuğunu', 'Fosillerin lavların içinde canlı kalarak taşlaştığını'], 'Altta denizel fosilli tortul kayaçların, üstte ise bazaltın bulunması, denizel çökelmeden sonra bölgede volkanik püskürme olduğunu kanıtlar.'),
  ('Fiziksel tortul bir kayaç olan kumtaşının yüksek sıcaklık ve basınç altında başkalaşmasıyla oluşan çok sert kayaç aşağıdakilerden hangisidir?', 'Kuvarsit', ['Gnays', 'Mermer', 'Antrasit'], 'Kuvars minerallerince zengin olan kumtaşı, yüksek ısı ve basınç altında başkalaşarak son derece sert olan kuvarsite dönüşür.'),
  ('İskoçya\'daki Devler Kaldırımı veya Sinop Boyabat\'taki sütunlu kayaçlar gibi altıgen prizma şekilli yapıların oluştuğu tipik dış püskürük kayaç hangisidir?', 'Bazalt', ['Siyenit', 'Traverten', 'Linyit'], 'Bazalt lavları soğuyup büzülürken genellikle beşgen veya altıgen prizmatik sütunlar şeklinde çatlayarak karakteristik bazalt sütunlarını oluşturur.'),
  ('Granit bloklarının zamanla fiziksel ve kimyasal ayrışmaya uğrayarak üst üste yığılmış köşeleri yuvarlaklaşmış kayalar oluşturmasıyla meydana gelen yer şekline ne ad verilir?', 'Tor topoğrafyası', ['Kırgıbayır (badlands) arazisi', 'Karstik polye tabanı', 'Buzul hörgüçkaya tepesi'], 'Derinlikte oluşan granit kütleleri yüzeye çıktığında çatlakları boyunca ayrışarak İskoçya\'da ve Aydın Çine\'de görülen tor topoğrafyasını oluşturur.'),
  ('Denizlerde yaşayan tek hücreli tebeşir canlılarının veya mercan iskeletlerinin deniz tabanında birikmesiyle oluşan kayaçlar hangi gruba girer?', 'Organik tortul kayaçlar', ['Kimyasal tortul kayaçlar', 'Derinlik magmatik kayaçlar', 'Metamorfik (başkalaşım) kayaçlar'], 'Mercan kalkeri, tebeşir ve radyolarit gibi kayaçlar hayvansal veya bitkisel organizma kalıntılarından oluştuğu için organik tortul kayaçtır.'),
  ('Sivas çevresinde geniş alanlar kaplayan ve karstik erime şekillerinin çok hızlı gelişip kısa sürede tahrip olmasına yol açan kimyasal tortul kayaç hangisidir?', 'Jips (Alçı taşı)', ['Granit (iç püskürük kayaç)', 'Kuvarsit (başkalaşım kayacı)', 'Bazalt (dış püskürük kayaç)'], 'Jips (alçı taşı), kalkere göre suda çok daha hızlı çözündüğü ve dayanıksız olduğu için üzerindeki karstik şekiller çabuk oluşup çabuk bozulur.'),
  ('Bir kayaç örneğinin incelemesinde; tabakalanma göstermediği, gözeneksiz olduğu, tamamının birbirine kenetlenmiş iri kuvars, feldspat ve mika kristallerinden oluştuğu görülmüştür. Bu kayaç büyük olasılıkla hangisidir?', 'Granit', ['Kumtaşı', 'Obsidiyen', 'Tebeşir'], 'Kuvars, feldspat ve mika minerallerinden oluşan, tabakasız, gözeneksiz ve iri kristalli masif kayaç granittir.'),
  ('Köşeli çakılların taşınmadan olduğu yerde veya çok kısa mesafede doğal bir çimento ile birleşmesiyle oluşan fiziksel tortul kayaç hangisidir?', 'Breş', ['Konglomera', 'Marn', 'Diyorit'], 'Çakıllar akarsularla uzun süre taşınmamışsa köşeli kalır; bu köşeli çakılların çimentolaşmasıyla breş oluşur.'),
  ('Organik tortul kayaçlar olan turba, linyit, taş kömürü ve antrasitin sıralanışında, turbadan antrasite doğru gidildikçe hangi özellik artar?', 'Karbon oranı ve kalori değeri', ['İçerdikleri su ve nem miktarı', 'Oluşumlarının yakınlığı', 'Gözeneklilik ve uçucu gaz oranı'], 'Turbadan antrasite doğru jeolojik yaş büyür, nem ve uçucu maddeler azalırken karbon oranı ile ısıl (kalori) değer artar.'),
  ('Bir bölgede başkalaşım (metamorfik) kayaçların yüzeye yakın yerlerde yaygın olarak bulunması, o bölgenin jeolojik geçmişi hakkında neyi gösterir?', 'Derinlerdeki kayaçların tektonik yükselme ve üstteki örtünün aşınmasıyla yüzeye çıktığını', ['Bölgede hiçbir zaman aşınma ve dış kuvvet faaliyetinin yaşanmadığını', 'Yüzeydeki kumların rüzgar etkisiyle doğrudan kristalleştiğini', 'Akarsuların taşıdığı alüvyonların soğuyarak başkalaşıma uğradığını'], 'Derinlerde yüksek basınç ve sıcaklıkla oluşan metamorfik kayaçların yüzeyde görülmesi, tektonik yükselme ve üzerindeki tabakaların aşındığını kanıtlar.'),
  ('Taş kömürünün yer kabuğunun derinliklerinde çok yüksek basınç ve sıcaklık altında kristalleşerek başkalaşmasıyla hangi değerli mineral/kayaç oluşur?', 'Elmas (veya grafit)', ['Mermer (kalsit kristali)', 'Zümrüt (beril minerali)', 'Obsidiyen (silisli cam)'], 'Saf karbon içeren kömür tabakaları çok yüksek basınç ve sıcaklık koşullarında başkalaşarak grafit veya elmasa dönüşür.'),
  ('Kapalı havzalardaki göllerin sularının kurak dönemlerde buharlaşması sonucunda göl tabanında biriken kaya tuzu ve jips hangi kayaç grubundadır?', 'Kimyasal tortul kayaçlar', ['Fiziksel (mekanik) tortul kayaçlar', 'Dış püskürük (volkanik) kayaçlar', 'Organik tortul kayaçlar'], 'Suda çözünmüş haldeki minerallerin buharlaşma etkisiyle çökelmesi sonucu oluşan kaya tuzu ve jips kimyasal tortul (evaporit) kayaçlardır.'),
  ('Aşağıdaki kayaç eşleştirmelerinden hangisinde iki kayaç da dış kuvvetlerin aşındırmasına karşı yüksek direnç gösteren sert kayaçlardan oluşur?', 'Granit - Kuvarsit', ['Volkan tüfü - Jips', 'Kaya tuzu - Kil taşı', 'Tebeşir - Pomza taşı'], 'Granit (iç püskürük) ve kuvarsit (kumtaşının başkalaşımı) kuvars içeriği yüksek, aşınmaya karşı son derece dirençli sert kayaçlardır.'),
  ('Kil ile kalkerin (kireç taşının) belirli oranlarda karışarak çökelmesiyle oluşan ve çimento sanayisinde hammadde olarak kullanılan tortul kayaç hangisidir?', 'Marn', ['Gabro', 'Andezit', 'Şist'], 'Kil ve kireç taşının karışımından oluşan marn, tortul bir kayaç olup çimento üretiminde yaygın olarak kullanılır.'),
  ('Tortul bir kayacın başkalaşım (metamorfizma) geçirmesi sürecinde kayacın yapısında aşağıdaki değişimlerden hangisinin gerçekleşmesi beklenmez?', 'Eriyerek tamamen sıvı magmaya dönüşmesi', ['İçindeki fosil izlerinin bozulması veya silinmesi', 'Minerallerin yeniden kristalleşerek dizilmesi', 'Yoğunluğunun ve sertliğinin artış göstermesi'], 'Metamorfizma katı halde gerçekleşen bir değişimdir; kayaç tamamen erirse başkalaşım kayacı değil magma oluşur ve soğuduğunda magmatik kayaç meydana gelir.'),
  ('Ankara Kalesi ve çevresindeki tarihi yapılarda yaygın olarak kullanıldığı için "Ankara taşı" olarak da bilinen pembemsi-gri dış püskürük kayaç hangisidir?', 'Andezit', ['Peridotit', 'Konglomera', 'Gnays'], 'Andezit, yüzey volkanizmasıyla oluşan dış püskürük bir kayaçtır ve İç Anadolu\'da özellikle Ankara çevresinde "Ankara taşı" adıyla bilinir.'),
  ('Kimyasal ayrışmanın çok şiddetli olduğu sıcak ve nemli iklim bölgelerinde aşağıdaki kayaçlardan hangisinin diğerlerine göre daha hızlı çözünmesi beklenir?', 'Kalker', ['Kuvarsit', 'Granit', 'Bazalt'], 'Sıcak ve nemli bölgelerde karbonik asitçe zengin sular, kalsiyum karbonat yapılı kalkeri hızla çözündürerek kimyasal ayrışmaya uğratır.'),
  ('Ekvatoral bölgede çok gür yağmur ormanları bulunmasına rağmen laterit toprakların humus bakımından fakir olmasının temel nedenlerinden biri nedir?', 'Aşırı yağışla yıkanma ve mikroorganizmaların humusu hızla tüketmesi', ['Yıllık sıcaklık ortalamasının bitki çürümesi için yetersiz kalması', 'Ana kayanın yalnızca kireç taşı ve kaya tuzundan meydana gelmesi', 'Buzul aşındırmasının üst toprak katmanını sürekli süpürmesi'], 'Ekvatoral iklimde sıcaklık ve nem çok yüksek olduğundan ayrıştırıcı canlılar organik maddeyi hızla tüketir, aşırı yağışlar da besin maddelerini yıkar.'),
  ('Akarsuların taşıdığı alüvyal topraklarda A, B ve C horizonlarının belirgin olarak görülmemesinin temel nedeni aşağıdakilerden hangisidir?', 'Dış kuvvetlerce taşınıp sürekli yenilenen genç malzemelerden oluşmaları', ['Sadece kurak çöl bölgelerinde ve kutup altlarında yayılış göstermeleri', 'Ana kayanın yerinde kimyasal çözülmesiyle milyonlarca yılda oluşmaları', 'Aşırı tuz ve kireç birikimi yüzünden katmanların tamamen kaynaşması'], 'Alüvyal, kolüvyal, lös ve moren gibi azonal (taşınmış) topraklar dış kuvvetlerce sürekli biriktirildiği için horizonlaşma (katmanlaşma) göstermezler.'),
  ('Dağlık alanlarda eğimli yamaçlar boyunca ufalanan malzemelerin yer çekimi ve sel sularıyla dağ eteklerinde birikmesi sonucu oluşan taşlı toprak hangisidir?', 'Kolüvyal topraklar', ['Hidromorfik topraklar', 'Halomorfik (tuzlu) topraklar', 'Kahverengi orman toprakları'], 'Eğimli yamaçlardan inen malzemelerin dağ eteklerinde birikmesiyle kolüvyal topraklar; ince kısımların yıkanıp iri taşların kalmasıyla da litosoller oluşur.'),
  ('Orta kuşağın nemli iklim bölgelerinde (örneğin Karadeniz kıyılarında) geniş yapraklı ormanlar altında gelişen, humusça zengin koyu renkli toprak hangisidir?', 'Kahverengi orman toprağı', ['Kestane renkli step toprağı', 'Tundra (bataklık) toprağı', 'Çöl (kumul ve tuz) toprağı'], 'Geniş yapraklı ağaçların her yıl dökülen yapraklarının çürümesiyle zengin bir humus katmanı kazanan bu topraklar kahverengi orman topraklarıdır.'),
  ('Yağış miktarının az, buharlaşmanın fazla olduğu yarı kurak bozkır ve çöl topraklarında kireç ile tuzun toprak yüzeyine yakın birikmesinin sebebi nedir?', 'Yıkanmanın yetersiz olması ve kapiler yolla yükselen suyun buharlaşması', ['Gür orman örtüsünün kökleriyle derinlerdeki tuzu yüzeye çıkarması', 'Şiddetli yağmurların üst katmandaki kili alt katmanlara indirmesi', 'Donmuş toprak tabakasının suyun derine sızmasını engellemesi'], 'Kurak ve yarı kurak bölgelerde yağış suyu toprağı derinlemesine yıkayamaz; kılcallıkla (kapilarite) yüzeye yükselen su buharlaşınca tuz ve kireç üstte kalır.'),
  ('Kutup altı bölgelerde yılın büyük bölümünde donmuş halde bulunan, yazın sadece üst kısmı çözülerek bataklığa dönüşen verimsiz toprak hangisidir?', 'Tundra toprakları', ['Laterit toprakları', 'Terra rossa toprakları', 'Alüvyal delta toprakları'], 'Tundra ikliminde permafrost (sürekli donmuş toprak) üzerinde yazın kısa süreli çözünmeyle balçık/bataklık halini alan organik ayrışması zayıf topraklardır.'),
  ('Rüzgarların kurak ve yarı kurak alanlardan aşındırdığı ince toz boyutundaki malzemeleri taşıyıp biriktirmesiyle oluşan azonal toprak hangisidir?', 'Lös', ['Moren', 'Regosol', 'Rendzina'], 'Rüzgarların taşıyıp biriktirdiği sarımsı ince malzemelerden oluşan taşınmış (azonal) topraklara lös, buzulların biriktirdiklerine ise moren denir.'),
  ('Volkanik arazilerden çıkan kum boyutundaki tüflü malzemeler ile akarsu birikintileri üzerinde oluşan, patates ve bağcılık tarımına çok elverişli azonal toprak hangisidir?', 'Regosoller', ['Halomorfik topraklar', 'Tundra toprakları', 'Laterit topraklar'], 'Nevşehir, Niğde ve Ağrı çevresinde volkanik kumlu ve tüflü depolar üzerinde oluşan regosoller gevşek dokulu olup yumrulu bitkiler ve bağcılık için idealdir.'),
  ('Türkiye\'de Doğu Karadeniz kıyılarındaki topraklarda kireç oranının İç Anadolu\'daki step topraklarına göre çok düşük olmasının temel etkeni nedir?', 'Yıllık yağış miktarının fazlalığına bağlı aşırı yıkanma', ['Ortalama yükseltinin deniz seviyesine daha yakın olması', 'Fiziksel (mekanik) ufalanmanın yıl boyu etkili olması', 'Rüzgar erozyonunun üstteki kireçli tabakayı taşıması'], 'Doğu Karadeniz\'de yağış çok fazla olduğu için topraktaki kireç ve tuz yıkanarak alt katmanlara veya yer altı suyuna taşınır, toprak asidik özellik kazanır.'),
  ('Eski göl tabanlarındaki killi ve kireçli depolar üzerinde oluşan, kurak dönemde derin çatlaklar açıp yağışlı dönemde şişen ve Trakya\'da "karakepir" denilen toprak hangisidir?', 'Vertisol (Dönen topraklar)', ['Podzol (Kül renkli topraklar)', 'Litosol (Taşlı yamaç toprakları)', 'Terra rossa (Kırmızı topraklar)'], 'Vertisoller kil oranı çok yüksek intrazonal topraklardır; kurak mevsimde çatlaklardan dökülen toprak yağışla şişince yukarı itildiği için dönen toprak denir.'),
  ('Taban suyu seviyesinin yüksek olduğu bataklık ve sazlık alanlarda, su altında oksijensiz koşullar nedeniyle gelişen intrazonal toprak hangisidir?', 'Hidromorfik topraklar', ['Kalsimorfik topraklar', 'Kahverengi bozkır toprakları', 'Kırmızımsı çöl toprakları'], 'Su (hidro) etkisi altında, drenajın kötü olduğu taban suyu yüksek alanlarda oluşan intrazonal topraklara hidromorfik topraklar denir.'),
  ('Erzurum-Kars platosunda dünyanın en verimli toprağı olan çernozyomların bulunmasına rağmen bölgede tarımsal ürün çeşitliliğinin az olması neyle açıklanır?', 'Yükseltiye bağlı olarak yaz süresinin kısa ve sıcaklıkların düşük olmasıyla', ['Toprağın aşırı tuzlu ve kireçli bir kimyasal yapıya sahip olmasıyla', 'Bölgede yıllık yağış miktarının çöl sınırının altında kalmasıyla', 'Toprak kalınlığının birkaç milimetreyi geçmeyecek kadar sığ olmasıyla'], 'Çernozyomlar mineral ve humusça çok zengin olsa da Erzurum-Kars\'ta sert karasal iklim (uzun soğuk kışlar, kısa serin yazlar) tarımsal çeşitliliği sınırlar.'),
  ('Toprak profilinde A horizonundan yıkanan kil, demir, alüminyum ve kireç gibi maddelerin çökelerek toplandığı katman aşağıdakilerden hangisidir?', 'B horizonu (Birikme katmanı)', ['O horizonu (Organik örtü katmanı)', 'C horizonu (Ayrışmamış kaya parçaları)', 'D horizonu (Ana kaya kütlesi)'], 'Yağış sularıyla A horizonundan süzülen ince kil ve çözünmüş mineraller hemen alttaki B horizonunda birikir; bu yüzden B katmanına birikme katmanı denir.'),
  ('Yumuşak kireç taşları ve marn tabakaları üzerinde oluşan, üst kısmı koyu renkli, alt kısmı kireççe zengin beyazımsı intrazonal toprak hangisidir?', 'Rendzina', ['Moren', 'Laterit', 'Podzol'], 'Kalsimorfik (kireçli) intrazonal topraklar ikiye ayrılır: killi-kireçli depolardaki vertisoller ve yumuşak kireç taşları üzerindeki rendzinalar.'),
  ('Terra rossa topraklarında turunçgil, zeytin ve sebze tarımı yapılırken çiftçilerin verimi artırmak için öncelikle uyguladığı yöntem aşağıdakilerden hangisidir?', 'Sulama ve organik/azotlu gübreleme yapmak', ['Toprağa bol miktarda kireç ve kaya tuzu eklemek', 'Toprağı yıkayarak içindeki demir oksidi uzaklaştırmak', 'Tarlaları nadasa bırakarak buharlaşmayı artırmak'], 'Terra rossalar yaz kuraklığı yaşayan Akdeniz ikliminde oluştuğu ve humusça çok zengin olmadığı için sulama ve gübreleme yapıldığında yüksek verim verir.'),
  ('Mohs sertlik ölçeğine göre kayaçları oluşturan mineraller sıralandığında, tırnakla bile çizilebilen jips ile camı kolayca çizebilen kuvars arasındaki fark neyi etkiler?', 'Kayaçların dış kuvvetlerin aşındırmasına karşı gösterdiği direnci', ['Kayaçların bulunduğu bölgenin yıllık ortalama güneşlenme süresini', 'Yeryüzündeki okyanus akıntılarının yönünü ve tuzluluk oranını', 'Atmosferdeki su buharının yoğunlaşarak yağışa dönüşme biçimini'], 'Sert minerallerden (örneğin kuvars) oluşan kayaçlar aşınmaya karşı dirençli olup yüksek tepeler oluştururken, yumuşak mineralli (jips, talk) kayaçlar kolay aşınır.'),
  ('Uludağ\'ın ana kütlesini oluşturan derinlik kayacı granitin, dağın oluşumu sırasında çevresindeki kalker tabakalarını ısıtarak mermere dönüştürmesi hangi tür başkalaşımdır?', 'Dokanak (kontakt) metamorfizması', ['Rüzgar biriktirme tortullanması', 'Biyolojik (organik) taşlaşma', 'Buharlaşmaya bağlı kimyasal çökelme'], 'Sıcak magmanın yer kabuğuna sokulurken temas ettiği (dokunduğu) yan kayaçları yüksek sıcaklıkla başkalaştırmasına dokanak (kontakt) metamorfizması denir.'),
  ('Silis (SiO2) bakımından zengin sularda yaşayan tek hücreli deniz canlılarının (radyolarya ve diyatome) kabuklarının çökelmesiyle oluşan sert organik tortul kayaç hangisidir?', 'Radyolarit (veya diyatomit)', ['Traverten (sıcak su çökeli)', 'Gabro (bazik derinlik kayacı)', 'Siyenit (nötr derinlik kayacı)'], 'Silisli kabuğa sahip mikroskobik canlıların deniz veya göl tabanında birikip taşlaşmasıyla radyolarit ve diyatomit gibi organik tortul kayaçlar oluşur.'),
  ('Zonguldak ve Bartın çevresinde demir-çelik sanayisinde yüksek fırınlarda enerji kaynağı olarak kullanılan Birinci Jeolojik Zaman (Paleozoyik) kayacı hangisidir?', 'Taş kömürü', ['Linyit kömürü', 'Volkan tüfü', 'Kaya tuzu'], 'Paleozoyik (Karbonifer) döneminde oluşan taş kömürü, yüksek kalorisi nedeniyle Karabük ve Ereğli demir-çelik fabrikalarında kok kömürü yapılarak kullanılır.'),
  ('Akdeniz Bölgesi\'nde Toros Dağları\'nda yüzey sularının fakir, buna karşılık yer altı suları ve karstik kaynakların (voklüz) çok zengin olmasının temel kayaç nedeni nedir?', 'Çatlaklı ve erime boşluklu kalker tabakalarının geniş yer kaplaması', ['Geçirimsiz kil taşı ve şist tabakalarının tüm yüzeyi örtmesi', 'Masif ve çatlaksız granit batolitlerinin su sızmasını önlemesi', 'Sürekli donmuş toprak tabakasının suları yüzeyde tutması'], 'Kalker (kireç taşı) suda çözünerek çatlak, düden ve mağara sistemleri oluşturduğundan yağış suları hızla yer altına sızar ve güçlü karstik kaynaklar doğar.'),
  ('Bir inşaat mühendisi deprem riski yüksek bir bölgede zemin etüdü yapmaktadır. Bina temeli için sıvılaşma riski taşımayan en sağlam zemin aşağıdaki kayaçlardan hangisidir?', 'Sağlam bazalt veya granit ana kaya', ['Yer altı suyu yüksek gevşek alüvyon', 'Suda hızla eriyen boşluklu jips kütlesi', 'Suya doygun yumuşak killi dolgu zemin'], 'Masif magmatik kayaçlar (granit, bazalt) ve sağlam kuvarsitler deprem dalgalarını büyütmeyen, sıvılaşma yapmayan en güvenilir temel zeminleridir.'),
  ('Doğu Anadolu Bölgesi\'nde Van Gölü çevresi, Kars, Ardahan ve Ağrı platolarında bazalt, andezit, obsidiyen ve tüf gibi kayaçların yaygın olması neyin sonucudur?', 'Yakın jeolojik geçmişte şiddetli volkanik faaliyetlerin yaşanmasının', ['Bölgenin tamamının mercan resifleriyle kaplı sığ bir deniz olmasının', 'Rüzgarların Sahra Çölü\'nden milyonlarca ton kum taşımasının', 'Buzul örtülerinin ana kayayı eriterek başkalaşıma uğratmasının'], 'Ağrı, Tendürek, Süphan ve Nemrut gibi volkanlardan çıkan lav ve küller Doğu Anadolu\'da geniş volkanik (dış püskürük) kayaç örtüleri oluşturmuştur.'),
  ('Fiziksel ufalanma sonucunda kayacın sadece boyutu küçülürken, kimyasal çözülme sonucunda kayacın mineral yapısı değişerek yeni maddeler oluşur. Buna göre feldspat mineralinin kimyasal ayrışmasıyla ne oluşur?', 'Kil mineralleri', ['Saf elmas kristalleri', 'Volkanik cam', 'Taş kömürü damarları'], 'Magmatik kayaçlarda bol bulunan feldspat mineralleri su ve karbonik asitle kimyasal çözülmeye uğradığında kil minerallerine dönüşerek toprak oluşumunu sağlar.'),
  ('Batı Anadolu\'da Menderes Masifi, Kırşehir ve Bitlis masifleri gibi yaşlı çekirdek arazilerde gnays, mikaşist ve mermerin bir arada bulunması bu arazilerin hangi özelliğini gösterir?', 'Metamorfik (başkalaşım) kayaçlardan oluşan eski ve sert kütleler olduğunu', ['Henüz taşlaşmamış genç akarsu alüvyonlarından meydana geldiğini', 'Aktif volkanların püskürttüğü taze lav akıntılarıyla kaplı olduğunu', 'Tamamen organik kökenli kömür ve tebeşir yataklarından oluştuğunu'], 'Masif araziler, eski jeolojik dönemlerde oluşup yüksek sıcaklık ve basınç altında başkalaşım geçirmiş gnays, şist ve mermer gibi kayaçlardan yapılı sert kütlelerdir.'),
  ('Muğla, Antalya ve Mersin çevresinde kıyı ovaları (örneğin Silifke ve Köyceğiz çevresi) hariç tutulduğunda, yamaçlarda yaygın olan terra rossa topraklarının tarımsal açıdan en belirgin kısıtlaması nedir?', 'Karstik arazide suyun derine sızması nedeniyle toprağın susuz kalması ve sığ olması', ['Yıl boyunca toprağın donmuş halde kalarak bitki köklerini çürütmesi', 'Aşırı yağıştan dolayı güneş ışığı görmemesi ve sürekli bataklık olması', 'Yüzeyinin metrelerce kalınlıkta hareketli çöl kumullarıyla örtülü olması'], 'Kalkerli karstik arazilerde su çatlaklardan hızla yer altına sızdığı için yüzeydeki terra rossa toprakları yazın kuraklık çeker ve engebeli yerlerde sığdır.'),
  ('Trakya\'da Ergene Havzası\'nda ayçiçeği ve buğday tarımının yoğun olarak yapıldığı "karakepir" (vertisol) topraklarının işlenmesini zorlaştıran temel fiziksel özellik nedir?', 'Ağır killi yapısı nedeniyle kuruyunca taş gibi sertleşmesi, ıslanınca yapışkan olması', ['Tamamen iri çakıl ve keskin kayalardan oluştuğu için pullukları kırması', 'Rüzgarla sürekli yer değiştiren gevşek kum tanelerinden meydana gelmesi', 'İçerisinde hiç mineral bulunmayan saf turba yosunlarından oluşması'], 'Vertisoller yüksek oranda şişebilen kil içerdiği için ıslakken çamurlaşıp tarım araçlarına yapışır, kuruduğunda ise derin çatlaklar açarak çok sertleşir.'),
  ('Çay bitkisi kireçsiz, yıkanmış ve asidik (pH 4.5 - 6.0) toprakları sever. Buna göre Türkiye\'de çay tarımının Rize ve çevresinde yoğunlaşmasını sağlayan toprak tipi hangisidir?', 'Aşırı yıkanmış asidik (lateritleşmiş) kahverengi orman toprakları', ['Kireç oranı çok yüksek kestane renkli bozkır toprakları', 'Tuz Gölü çevresindeki yüksek bazik halomorfik topraklar', 'Kalker üzerinde gelişmiş kireçli rendzina toprakları'], 'Doğu Karadeniz\'de bol yağışla kireci ve tuzu tamamen yıkanmış, asidik karakter kazanmış lateritik özellikli kahverengi orman toprakları çay için idealdir.'),
  ('Kurak ve yarı kurak bölgelerde yapılan aşırı ve bilinçsiz (vahşi/salma) sulama, uzun vadede verimli tarım topraklarında hangi çevre sorununa yol açar?', 'Buharlaşmayla taban suyundaki tuzun yüzeye çıkmasına ve toprağın çoraklaşmasına', ['Toprağın hızla podzolleşerek soğuk kuşak iğne yapraklı orman toprağına dönüşmesine', 'Ana kayanın eriyerek magmatik bazalt ve granit kütleleri oluşturmasına', 'Topraktaki humus miktarının aşırı artarak bataklık turbasına dönüşmesine'], 'Drenajın yetersiz olduğu sıcak-kurak ovalarda (örneğin Harran Ovası\'nda geçmişte yaşandığı gibi) aşırı sulama taban suyunu yükseltir; su buharlaşınca tuz yüzeyde birikir (tuzlanma/çoraklaşma).'),
  ('Akarsuların dağ içlerinden ovaya açıldığı yerlerde eğimin aniden azalmasıyla oluşan birikinti konisi ve yelpazelerinde hangi toprak tipi yaygındır?', 'Kolüvyal topraklar', ['Tundra toprakları', 'Laterit topraklar', 'Hidromorfik topraklar'], 'Dağ yamaçlarından sel ve derelerin taşıdığı kumlu-çakıllı geçirimli malzemelerin dağ eteklerindeki birikinti konilerinde yığılmasıyla kolüvyal topraklar oluşur.'),
  ('Batı Karadeniz\'de (Bolu, Kastamonu, Zonguldak yüksekleri) sarıçam, köknar ve ladin ormanları altında gelişen podzol toprakların kül renginde (boz-gri) olmasının nedeni nedir?', 'A horizonundaki demir ve organik maddelerin yıkanıp geriye açık renkli silis kalması', ['Volkanik patlamalarla gökyüzünden sürekli beyaz kül ve pomza yağması', 'Yüzeyde yoğun miktarda kaya tuzu ve jips kristallerinin çökelmesi', 'Kalker kayacının çözünmeden beyaz toz halinde üst katmanı kaplaması'], 'Soğuk-nemli iklimde iğne yapraklı ağaçların oluşturduğu asidik ortamda demir, alüminyum ve humus alt katmana yıkanır; A horizonunda kuvarsça zengin kül renkli (boz) bir katman kalır.'),
  ('Aşağıdaki ekonomik faaliyet ve toprak/kayaç eşleştirmelerinden hangisi hammadde ilişkisi bakımından yanlıştır?', 'Cam sanayisi - Yüksek demirli bazalt ve kömür', ['Çimento sanayisi - Marn', 'Seramik ve porselen sanayisi - Kaolin (saf kil) ve feldspat', 'Alçı ve kartonpiyer üretimi - Jips (alçı taşı) kayacı'], 'Cam sanayisinin temel hammaddesi saf kuvars kumu (silis), kireç taşı ve sodadır; koyu renkli bazalt veya kömür cam üretim hammaddesi değildir.'),
  ('Tuğla imalatında Ekvatoral bölgedeki yerli toprakların güneşte kurutulduğunda beton gibi sertleşmesinden yararlanılır. Zaten Latince "tuğla" anlamına gelen bu toprak hangisidir?', 'Laterit', ['Lös', 'Çernozyom', 'Moren'], 'Demir ve alüminyum oksitçe çok zengin olan laterit (Latince "later" = tuğla), nemliyken kesilip güneşte kurutulduğunda tuğla gibi sertleştiği için yapı malzemesi olarak kullanılır.'),
  ('Nadas uygulaması, yarı kurak bölgelerde toprağın su ve azot dengesini korumak için bir yıl ekilip bir yıl boş bırakılmasıdır. Ancak nadasa bırakılan tarlada hangi risk belirgin şekilde artar?', 'Bitki örtüsünden yoksun kalan gevşek üst toprağın rüzgar ve su erozyonuyla taşınması', ['Toprağın altındaki kireç taşının başkalaşarak mermere dönüşmesi', 'Toprak sıcaklığının düşerek kalıcı permafrost (donmuş toprak) oluşması', 'B horizonundaki kilin kendiliğinden volkanik tüfe dönüşmesi'], 'Nadas döneminde sürülmüş ancak bitkisiz bırakılmış çıplak toprak yüzeyi rüzgar ve sağanak yağışların aşındırmasına (erozyona) açık hale gelir; bu yüzden nöbetleşe ekim önerilir.'),
  ('Dağların güneye bakan yamaçları (Kuzey Yarım Küre\'de) kuzeye bakan yamaçlarına göre daha fazla güneş enerjisi alır. Bu "bakı" faktörünün toprak oluşumuna etkisi nasıldır?', 'Bakılı yamaçta sıcaklık farkları, buharlaşma ve ayrışma süreçleri diğer yamaca göre farklılaşır', ['Bakı faktörü ana kayanın magmatik veya tortul olma özelliğini baştan sona değiştirir', 'Kuzeye bakan yamaçlarda her zaman çöl toprağı, güneyde ise laterit oluşmasını sağlar', 'Toprağın yer çekimiyle taşınmasını durdurarak tüm eğimli yamaçları düzleştirir'], 'Bakı etkisiyle güney ve kuzey yamaçlar arasında güneşlenme, ısınma, karın yerde kalma süresi, nemlilik ve bitki örtüsü değiştiğinden toprak oluşum hızı ve tipi de etkilenir.'),
  ('Nevşehir-Ürgüp yöresinde volkan tüflerinin içinde halkın kolayca kayaları oyarak yer altı şehirleri, soğuk hava depoları ve konutlar yapabilmesi tüfün hangi özelliğinden kaynaklanır?', 'Kazılması kolay yumuşak bir yapıda olup havayla temas edince yüzeyinin kısmen sertleşmesinden', ['Elmastan daha sert olduğu için hiçbir depremde ve heyelanda sarsılmamasından', 'Suda kolayca eriyerek kendiliğinden düzgün odalar ve koridorlar oluşturmasından', 'İçerisinde bol miktarda taş kömürü barındırdığı için kışın kendiliğinden ısınmasından'], 'Volkan tüfleri gözenekli ve yumuşak dokulu olduğundan kolayca oyulabilir, havayla temas eden yüzeyleri sertleşerek dayanıklılık kazanır ve iyi ısı yalıtımı sağlar.'),
  ('Çöl bölgelerinin kenarlarındaki çok az yağış alan yarı kurak bozkırlarda görülen, organik maddesi çok az ve kireç oranı yüksek "boz" renkli step toprağına ne ad verilir?', 'Sierozem (Boz step toprağı)', ['Çernozyom (Kara çayır toprağı)', 'Terra rossa (Kızıl Akdeniz toprağı)', 'Andosol (Volkanik kül toprağı)'], 'Çöl toprakları ile kahverengi step toprakları arasındaki geçiş kuşağında oluşan açık gri-boz renkli, humusça fakir kurakçıl topraklara sierozem denir.'),
  ('Karstik şekillerden lapya, dolin, uvala ve polyenin üzerinde biriken ve Akdeniz Bölgesi\'nde tarım için en elverişli alanları oluşturan kırmızı topraklar nerede en kalın örtüyü oluşturur?', 'Polye (gölova) tabanlarında', ['Dik kalker yamaçlarında', 'Keskin lapya sırtlarında', 'Mağara tavanlarında'], 'Karstik erime çukurlarının en genişi olan polyelerin (Elmalı, Korkuteli, Kestel, Tefenni ovaları) düz tabanlarında yamaçlardan taşınan terra rossalar kalın ve verimli bir örtü oluşturur.'),
  ('Bir bölgede granit kayacının ayrışmasıyla oluşan topraklar genellikle kumlu ve geçirimli olurken, bazalt veya kalkerin ayrışmasıyla oluşan toprakların daha killi olması neyi gösterir?', 'Ana kayanın mineral bileşiminin toprağın dokusunu (bünyesini) belirlediğini', ['İklimin toprak oluşumu üzerinde hiçbir etkisinin bulunmadığını', 'Granitin sadece çöllerde, bazaltın ise sadece bataklıklarda ayrıştığını', 'Kumlu toprakların her zaman killi topraklardan daha yaşlı olduğunu'], 'Granit bol miktarda çözünmeyen kuvars içerdiğinden ayrıştığında kumlu toprak verir; kuvars içermeyen bazalt veya saf olmayan kalker ise ayrıştığında ince killi topraklar oluşturur.'),
  ('Eğimli tarım arazilerinde su erozyonunu azaltmak için çiftçilerin tarlayı sürerken uygulaması gereken en doğru yöntem aşağıdakilerden hangisidir?', 'Tarlayı eğim yönüne dik (eş yükselti eğrilerine paralel) sürmek', ['Tarlayı yukarıdan aşağıya doğru eğim yönüne paralel sürmek', 'Hasat sonrasında tarladaki anızı yakarak yüzeyi temizlemek', 'Yamaçtaki çalı ve ağaççıkları sökerek tarla alanını genişletmek'], 'Eğime dik sürülen saban izleri küçük setler oluşturarak yağış suyunun hızını keser, suyun toprağa sızmasını sağlar ve üst toprağın süpürülmesini önler.'),
  ('Mermer ocaklarının işletilmesi sırasında ortaya çıkan ince mermer tozları tarım arazilerine ve akarsulara karıştığında çevresel olarak hangi kimyasal etkiyi yapar?', 'Kalsiyum karbonat içeriğiyle ortamın kireç oranını ve bazikliğini (pH) artırır', ['Yüksek kükürt oranıyla kuvvetli asit yağmurlarının oluşmasına neden olur', 'Toprağı radyoaktif elementlerle zenginleştirerek verimi iki katına çıkarır', 'İçerdiği yoğun sodyum klorür nedeniyle tatlı su kaynaklarını tuzlandırır'], 'Mermerin ana bileşeni kalsiyum karbonattır (CaCO3); ince tozları su ve toprağa karıştığında kireçlenmeye, gözeneklerin tıkanmasına ve pH değerinin bazik yönde artmasına yol açar.'),
  ('Kayaçların doğada katı halden ayrışmaya, tortullanmaya, başkalaşıma ve eriyerek magmaya, oradan tekrar katılaşmaya uzanan kesintisiz serüvenine ne ad verilir?', 'Kayaç döngüsü', ['Hidrolojik döngü', 'Azot döngüsü', 'Orojenez süreci'], 'Yer kabuğundaki magmatik, tortul ve metamorfik kayaçların iç ve dış kuvvetlerin etkisiyle sürekli birbirine dönüşmesi sürecine kayaç döngüsü denir.'),
  ('Antep fıstığı ve bağcılık tarımının Güneydoğu Anadolu\'da (Gaziantep, Şanlıurfa) yaygın olarak yapıldığı topraklar hangi iklim ve toprak grubuna dahildir?', 'Yarı kurak iklimin kahverengi/kırmızımsı kahverengi bozkır ve kireçli toprakları', ['Soğuk nemli iklimin aşırı yıkanmış kül renkli podzol toprakları', 'Sert karasal iklimin yüksek dağ çayırları altındaki çernozyomları', 'Kutup altı kuşağının sürekli donmuş bataklık tundra toprakları'], 'Güneydoğu Anadolu\'da kuraklığa dayanıklı Antep fıstığı, zeytin ve üzüm bağları kireççe zengin kırmızımsı kahverengi bozkır ve kalkerli topraklarda iyi yetişir.'),
  ('Deniz tabanında biriken tortul tabakaların milyonlarca yıl sonra binlerce metre yüksekliğindeki Toros ve Himalaya dağlarının zirvelerinde fosilli kalker olarak bulunması neyle açıklanır?', 'Levha hareketlerine bağlı orojenez (dağ oluşumu) ile deniz tabanının kıvrılıp yükselmesiyle', ['Geçmişte deniz seviyesinin bugünkünden sekiz bin metre daha yüksek olmasıyla', 'Rüzgarların deniz kıyısındaki fosilleri dağların zirvesine kadar uçurmasıyla', 'Volkanların deniz altındaki fosilleri eritmeden zirvelere püskürtmesiyle'], 'Tetis Denizi tabanında biriken kalın tortul (kalker, kil, kumtaşı) tabakalar Alp-Himalaya orojenezi sırasında yan basınçlarla kıvrılıp yükselerek yüksek sıradağları oluşturmuştur.'),
  ('Kuvarsit, mermer, şist ve gnays gibi kayaçların ortak özelliği düşünüldüğünde, bu kayaçların oluşumu için zorunlu olan iki temel fiziksel etken nedir?', 'Yüksek sıcaklık ve yüksek basınç', ['Şiddetli rüzgar ve kuraklık', 'Düşük sıcaklık ve don olayı', 'Bitki kökleri ve humus birikimi'], 'Başkalaşım (metamorfizma) olayının gerçekleşebilmesi için kayaçların yer kabuğunun derinliklerinde veya magma temasında yüksek sıcaklık ve yüksek basınca maruz kalması gerekir.'),
  ('Sivas çevresindeki jips karstında büyük mağara ve derin polyelerin Toroslar\'daki kalker karstı kadar uzun ömürlü ve belirgin olmamasının temel nedeni nedir?', 'Jipsin çok hızlı çözünüp kolay aşınması ve dayanıksız olması', ['Sivas çevresinde yıllık yağış tutarının Akdeniz\'den fazla olması', 'Jips tabakalarının hiçbir zaman yer yüzeyine çıkmaması', 'Bölgede rüzgâr biriktirme faaliyetlerinin karstlaşmayı tamamen durdurması'], 'Jips (alçı taşı) kalkere göre suda çok daha hızlı çözünür ve mekanik direnci düşüktür; bu yüzden oluşan şekiller çabuk tahrip olur ve büyük yapılar uzun süre korunamaz.'),
  ('Harita üzerinde Muğla, Castellorizo kuzeyi, Elmalı, Korkuteli, Acıpayam ve Tefenni arasında araştırma yapan bir coğrafyacı öncelikle hangi yer şeklini incelemektedir?', 'Polye ovalarını', ['Barkan kumullarını', 'Buzul vadilerini', 'Volkanik kalderaları'], 'Tefenni, Acıpayam, Korkuteli, Kestel, Elmalı ve Muğla ovaları Batı Toroslar ve Göller Yöresi\'nde yer alan Türkiye\'nin en karakteristik polye ovalarıdır.'),
  ('Tabanında düdenler bulunan Kestel ve Elmalı gibi polye ovalarında kış ve ilkbahar aylarında geçici göllerin oluşması aşağıdakilerden hangisiyle doğrudan açıklanır?', 'Düdenlerin alüvyonlarla tıkanması veya gelen suyun boşaltım kapasitesini aşmasıyla', ['Yaz mevsiminde buharlaşmanın tamamen durup yer altı suyunun donmasıyla', 'Deniz seviyesinin yükselerek kıyıdan polye tabanına tuzlu su basmasıyla', 'Rüzgârların taşıdığı lös depolarının yer altı mağaralarını ısıtmasıyla'], 'Polye tabanındaki düdenler (suyutanlar) kil ve çamurla tıkandığında ya da sağanak yağışlarla gelen su miktarı düdenin taşıma kapasitesini aştığında ova tabanını geçici olarak su basar.'),
  ('Karstik arazilerde yüzeysel akışın zayıf, buna karşılık yer altı suyu bakımından zengin kaynakların yaygın olmasının temel sebebi aşağıdakilerden hangisidir?', 'Çatlaklı ve geçirgen kalker yapısının yağış sularını hızla yer altına sızdırması', ['Buharlaşma şiddetinin her mevsim yağış miktarından birkaç kat fazla olması', 'Bitki örtüsünün tüm yağış sularını kökleriyle tutup atmosfere geri vermesi', 'Toprak tabakasının çok kalın ve geçirimsiz kil minerallerinden oluşması'], 'Kalkerli araziler bol çatlaklı ve erime boşluklu olduğundan yağmur ve kar suları yüzeyde akışa geçemeden hızla yer altına sızar ve voklüz kaynaklarını besler.'),
  ('Karstik bölgelerde yer altına sızan suların tek bir ağızdan bol debili ve basınçlı biçimde yüzeye çıktığı gür kaynaklara ne ad verilir?', 'Voklüz', ['Artezyen kaynağı', 'Gayzer kaynağı', 'Yamaç kaynağı'], 'Voklüz kaynakları, karstik boşluklarda biriken yer altı sularının kireçli ve soğuk karakterde, yağışlı dönemlerde debisi artacak biçimde yüzeye çıktığı kaynaklardır.'),
  ('Bir mağaranın içinde hem tavandan uzanan sarkıtların hem de tabandan yükselen dikitlerin çok yoğun bulunması, o mağara hakkında aşağıdakilerden hangisini kanıtlar?', 'Mağara tavanından kalsiyum bikarbonatça zengin suların uzun süre sızdığını ve içeride çökelme yaşandığını', ['Mağaranın rüzgâr aşındırmasıyla kurak bir çöl ikliminde yakın zamanda açıldığını', 'Mağara içindeki sıcaklığın sürekli sıfır derecenin altında kalarak suyun donduğunu', 'Mağaranın yalnızca mekanik dalga aşındırmasıyla deniz kıyısında şekillendiğini'], 'Sarkıt ve dikitler (damlataşlar), mağara tavanındaki çatlaklardan sızan kireçli su damlalarının içindeki CO2 gazının ayrışması ve CaCO3\'ün çökelmesiyle uzun süreçte oluşur.'),
  ('Denizli Pamukkale travertenlerinin beyaz rengini koruyabilmesi için suyun kontrollü şekilde farklı kanallara verilmesinin temel gerekçesi aşağıdakilerden hangisidir?', 'Termal suyun yeni kalsiyum karbonat çökeltmesini sağlamak ve yosunlaşma-kararmayı önlemek', ['Traverten basamaklarını tamamen eriterek altındaki granit kayacı ortaya çıkarmak', 'Suyun sıcaklığını düşürerek travertenlerin obruklara dönüşmesini hızlandırmak', 'Bölgedeki rüzgâr hızını artırarak yüzeyde barkan tepeleri oluşturmak'], 'Travertenlerin beyazlığı taze kalsiyum karbonat çökelmesine ve yüzeyin aşırı nemli kalıp alg-yosun tutmamasına bağlıdır; bu nedenle su dönüşümlü verilir.'),
  ('Bir mühendislik ekibi kalker tabakalarının çok kalın ve bol çatlaklı olduğu bir vadiye baraj inşa etmek istediğinde karşılaşacağı en ciddi hidrojeolojik risk hangisidir?', 'Baraj gölünde birikecek suların düdenler ve erime çatlakları yoluyla yer altına kaçması', ['Baraj tabanında birkaç gün içinde rüzgâr etkisiyle yardang sırtlarının oluşması', 'Kalker kayacının suyla temas edince aniden volkanik patlama göstermesi', 'Göl yüzeyinde aşırı lös birikmesi nedeniyle türbinlerin tamamen kumla dolması'], 'Geçirgen ve karstik erime boşluklarına sahip kireç taşı sahalarında baraj gölü suları çatlak ve düdenlerden sızarak su tutma kapasitesini düşürebilir (örn. Keban ve Oymapınar\'da özel yalıtım gerekmiştir).'),
  ('Toros Dağları\'nın yüksek kesimlerinde yüzeyin keskin sırtlı lapyalarla kaplı olması ekonomik faaliyetlerden hangisini doğrudan güçleştirir?', 'Tarımsal sürüm yapılmasını ve ulaşım-yürüyüş faaliyetlerini', ['Yer altı sularının kireç çözmesini ve mağara gelişimini', 'Akdeniz kıyılarında yaz turizmi sezonunun başlamasını', 'Kış aylarında yüksek kesimlere kar yağışı düşmesini'], 'Lapyalı yüzeyler (karren alanları) keskin dişli, yarıklı ve çıplak kayalık yapıda olduğundan toprağın tutunmasını, tarla sürümünü ve yaya/araç geçişini çok zorlaştırır.'),
  ('Antalya kent merkezinin üzerine kurulduğu geniş basamaklı düzlüklerin oluşumunda temel etken aşağıdakilerden hangisidir?', 'Karstik kaynak sularının binlerce yıl boyunca geniş çaplı traverten taraçaları biriktirmesi', ['Kızılırmak ve Yeşilırmak nehirlerinin bölgeye alüvyal delta malzemesi taşıması', 'Şiddetli çöl rüzgârlarının Toros eteklerinde kalın lös tabakaları yığması', 'Buzulların aşındırdığı moren setlerinin deniz kıyısında birleşmesi'], 'Antalya (Kırkgöz kaynakları beslemeli) traverten platosu, dünyanın en geniş alana yayılan basamaklı karstik traverten düzlüklerinden biridir.'),
  ('Konya Havzası\'ndaki Kızören, Çıralı ve Meyil obruklarının içinde göl bulunurken bazı obrukların kuru olmasını belirleyen temel faktör nedir?', 'Obruk tabanının bölgesel yer altı su tablası seviyesinin altına inip inmemesi', ['Obruğun kuzey veya güney yamacının rüzgâr yönüne bakıp bakmaması', 'Çevredeki tarım arazilerinde yetiştirilen ürünlerin hasat zamanı', 'Obruk ağzının dairesel ya da elips biçiminde şekillenmiş olması'], 'Çökme sonucu oluşan obruğun tabanı yer altı su seviyesinin (su tablasının) altına kadar inmişse tabanda obruk gölü oluşur; su tablasının üzerinde kalmışsa kuru obruk olarak kalır.'),
  ('Tokat\'ın Pazar ilçesi yakınlarında bulunan ve soğan sarkıtlarıyla dünyaca tanınan karstik mağara aşağıdakilerden hangisidir?', 'Ballıca Mağarası', ['Damlataş Mağarası', 'Karain Mağarası', 'Dupnisa Mağarası'], 'Tokat Pazar\'daki Ballıca Mağarası, kristalize kireç taşı içinde gelişmiş salonları ve nadir görülen soğan sarkıtlarıyla ünlü bir karstik mağaradır.'),
  ('Kırklareli\'nin Demirköy ilçesi sınırlarında, Istıranca (Yıldız) Dağları\'nda yer alan Trakya\'nın turizme açık en bilinen karstik mağarası hangisidir?', 'Dupnisa Mağarası', ['İnsuyu Mağarası', 'Dim Mağarası', 'Kaklık Mağarası'], 'Dupnisa Mağarası, Kırklareli Demirköy\'de mermerleşmiş kireç taşları içinde gelişmiş, içinden yer altı deresi geçen ünlü bir karstik mağara sistemidir.'),
  ('Denizli\'nin Honaz ilçesindeki Kaklık Mağarası\'na "Yer Altı Pamukkalesi" denilmesinin temel nedeni aşağıdakilerden hangisidir?', 'Tavanı çökmüş mağara içinde termal suların basamaklı travertenler oluşturması', ['Mağara girişinde dev boyutlu barkan ve kumul tepelerinin bulunması', 'İçerideki kayaların rüzgâr korrazyonu ile mantarkaya şeklini alması', 'Mağaranın tamamen kaya tuzu tabakaları içinde açılmış olması'], 'Kaklık Mağarası\'nda kükürtlü termal kaynak suları çöküntü ağzından içeri akarken Pamukkale\'dekine çok benzeyen beyaz traverten basamakları oluşturmuştur.'),
  ('Aşağıdaki kimyasal tepkime süreçlerinden hangisi kalker kayacının çözünerek karstik aşınım şekillerinin oluşmasını doğrudan açıklar?', 'Karbondioksitli suyun kalsiyum karbonatı suda çözünebilen kalsiyum bikarbonata dönüştürmesi', ['Suyun buharlaşmasıyla sodyum klorür kristallerinin çöl yüzeyinde kabuk bağlaması', 'Feldspat minerallerinin nemli iklimde ayrışarak kaolin kiline dönüşmesi', 'Demir minerallerinin oksijenle birleşerek kayaç yüzeyini paslandırması'], 'Yağmur suyu havadaki ve topraktaki CO2\'yi alarak zayıf karbonik asit oluşturur; bu su CaCO3 (kalker) ile tepkimeye girerek suda çözünen kalsiyum bikarbonatı meydana getirir.'),
  ('Karstik bir polye ovasında tarım yapan çiftçilerin kış yağışlarından sonra tarlalarının haftalarca su altında kalmasını önlemek için başvurabileceği en uygun doğal-teknik önlem nedir?', 'Ova kenarındaki düden ağızlarını dal, çöp ve alüvyon tıkanıklıklarından temizlemek', ['Ovanın ortasına rüzgâr hızını kesecek yüksek kumul setleri yığmak', 'Polye yamaçlarındaki tüm kireç taşı bloklarını dinamitle patlatmak', 'Toprak yüzeyini geçirimsiz kil ve beton tabakasıyla tamamen kaplamak'], 'Polye havzalarının doğal drenaj kanalları düdenlerdir; düden ağızlarının açık tutulması fazla suyun yer altına tahliyesini sağlayarak taşkın süresini kısaltır.'),
  ('Köprüçay, Manavgat ve Dalaman gibi Akdeniz akarsularının yaz kuraklığına rağmen yıl boyunca nispeten düzenli su taşımasında aşağıdakilerden hangisi etkilidir?', 'Havzalarındaki zengin karstik yer altı suları ve voklüz kaynaklarıyla beslenmeleri', ['Yaz aylarında Toros Dağları\'na her gün düzenli muson yağmurlarının düşmesi', 'Akarsu yataklarının rüzgâr biriktirmesiyle oluşan lös depolarıyla kaplı olması', 'Denizden karaya doğru esen meltem rüzgârlarının akarsu suyunu geri itmesi'], 'Akdeniz ikliminde yazlar kurak geçmesine karşın Toroslar\'daki geniş karstik rezervuarlardan çıkan gür kaynaklar Manavgat ve Köprüçay gibi nehirlerin debisini yazın da destekler.'),
  ('Bir akarsuyun karstik plato yüzeyini derinlemesine yararak oluşturduğu dik duvarlı, dar ve derin vadilere ne ad verilir?', 'Karstik kanyon vadi', ['Tabanlı alüvyal vadi', 'Buzul tekne vadisi', 'Asimetrik yatık vadi'], 'Kalker gibi dirençli ve dik durabilen karstik kayaçlarda akarsuların ve yer altı mağara çökmelerinin etkisiyle Köprülü Kanyon ve Göksu Kanyonu gibi dik yamaçlı kanyon vadiler gelişir.'),
  ('Antalya\'nın Döşemealtı ilçesi yakınlarında bulunan ve Anadolu\'daki en eski insan yerleşim izlerini barındıran doğal karstik mağara hangisidir?', 'Karain Mağarası', ['Ballıca Mağarası', 'Astım Mağarası', 'Tuz Mağarası'], 'Karain Mağarası, Antalya\'nın kuzeybatısında kalker yamaçta gelişmiş doğal bir karstik mağara olup Paleolitik Çağ\'dan itibaren yerleşim görmüştür.'),
  ('Çankırı\'da turizm ve sağlık amacıyla da ziyaret edilen büyük yer altı boşlukları hangi karstik kayaç türü içerisinde yer alır?', 'Kaya tuzu', ['Kalker', 'Dolomitik mermer', 'Tebeşir tabakası'], 'Çankırı Tuz Mağarası, suda çok kolay çözünebilen kaya tuzu (halit) yatakları içerisinde yer alan ve kaya tuzu işletmeciliğiyle de genişlemiş bir yer altı boşluğudur.'),
  ('Teke ve Taşeli platolarında tarım alanlarının çok parçalı ve sınırlı kalması, nüfus yoğunluğunun ise kıyı ovalarına göre düşük olması aşağıdakilerden hangisinin sonucudur?', 'Engebeli karstik topografyanın, yüzey suyu azlığının ve ince toprak örtüsünün', ['Yıllık sıcaklık ortalamasının tarım ürünlerinin yetişmesine izin vermeyecek kadar düşük olmasının', 'Şiddetli çöl rüzgârlarının tüm bölgeyi hareketli barkan kumullarıyla kaplamasının', 'Aktif volkanik gaz çıkışlarının yerleşim alanlarını sürekli tehdit etmesinin'], 'Teke ve Taşeli platoları kalkerli, bol çatlaklı, yüzey suyu fakiri ve engebeli karstik sahalar olduğu için geniş tarım alanları nadirdir ve nüfus seyrektir.'),
  ('Bir doğa yürüyüşü grubu önce dar erime oluklarından geçmiş, ardından huni biçimli birkaç küçük çanağı aşmış ve en son kenarında suyutan bulunan geniş düz bir ovaya ulaşmıştır. Grubun sırasıyla gördüğü şekiller hangisinde doğru verilmiştir?', 'Lapya - Dolin - Polye', ['Barkan - Yardang - Hamada', 'Sarkıt - Dikit - Traverten', 'Tafoni - Şahitkaya - Obruk'], 'Dar erime olukları lapya, huni biçimli çanaklar dolin, kenarında suyutan (düden) bulunan geniş düz karstik ova ise polyedir.'),
  ('Karstik bölgelerde gelişen doğal köprülerin oluşum mekanizması aşağıdakilerden hangisinde doğru açıklanmıştır?', 'İçinden yer altı akarsuyu geçen bir mağaranın tavanının büyük ölçüde çöküp yalnızca bir kısmının ayakta kalması', ['Rüzgârın taşıdığı kum tanelerinin iki ayrı tepeyi üstten birbirine çimentolaması', 'Traverten basamaklarının akarsu yatağı boyunca barkan kumullarıyla birleşmesi', 'Dolin tabanındaki terra rossa topraklarının donarak kemer biçiminde yükselmesi'], 'Karstik doğal köprüler (örneğin Yerköprü oluşumları), yer altı akarsu tünellerinin tavanlarının yer yer çökmesi ve sağlam kalan tavan parçasının köprü gibi vadiyi birleştirmesiyle oluşur.'),
  ('Soğuk kuşakta veya yüksek dağ zirvelerinde kar erime sularının karbondioksit bakımından zengin olması karstlaşmayı nasıl etkiler?', 'Soğuk su daha fazla karbondioksit çözebildiği için kireç taşının kimyasal çözünme kapasitesini artırır', ['Su sıcaklığı düştükçe kalsiyum karbonat hiç çözünmeden anında travertene dönüşür', 'Kar suları saf olduğu için kalker yüzeyinde hiçbir kimyasal aşındırma yapamaz', 'Soğuk su yalnızca mekanik rüzgâr aşındırmasını hızlandırarak mantarkaya oluşturur'], 'Gazların (CO2) sudaki çözünürlüğü düşük sıcaklıklarda arttığından, kar erime suları karbondioksitçe zenginleşir ve kalkeri çözme gücü yükselir.'),
  ('Rüzgârın yeryüzünü şekillendirirken gevşek ince malzemeyi havalandırıp süpürmesine ve taşıdığı kumları kayalara çarptırarak aşındırmasına sırasıyla ne ad verilir?', 'Deflasyon - Korrazyon', ['Karstlaşma - Çökelme', 'Abrazyon - Regresyon', 'Sirkülasyon - Transgresyon'], 'Rüzgârın ince kırıntıları üfleyip süpürmesine deflasyon (üfleme), taşıdığı kum tanelerini kayalara zımpara gibi çarptırarak yaptığı mekanik aşındırmaya ise korrazyon denir.'),
  ('Bir barkan kumulunun enine ve boyuna profili incelendiğinde rüzgârın geldiği yön ile barkanın şekli arasında nasıl bir ilişki görülür?', 'Rüzgârın çarptığı dışbükey yamaç az eğimli, içbükey yamaç diktir ve barkanın iki ucu rüzgârın ilerlediği yöne doğru uzanır', ['Rüzgârın çarptığı yamaç uçurum gibi diktir ve hilalin iki sivri ucu rüzgârın doğduğu kaynağa doğru bakar', 'Barkanın tüm yamaçları simetrik eğime sahiptir ve rüzgâr yönünden bağımsız olarak dairesel büyür', 'Barkanlar rüzgâr yönüne dik değil, yer altı su akış yönüne paralel olarak sabit kalır'], 'Barkanlarda kum taneleri rüzgârın geldiği az eğimli sırt boyunca yukarı sürüklenir ve tepeden rüzgâr altı dik yamaca dökülür; kenarlar daha hızlı ilerlediği için sivri uçlar esiş yönünü gösterir.'),
  ('Konya\'nın Karapınar ilçesinde 1960\'lı yıllarda yerleşim yerlerini ve tarım alanlarını tehdit eden hareketli kumulların durdurulmasında en kalıcı başarı hangi yöntemle sağlanmıştır?', 'Rüzgâr perdeleri oluşturulup kuraklığa dayanıklı bitkilerle sahanın ağaçlandırılması ve bitkilendirilmesiyle', ['Kumul tepelerinin kamyonlarla taşınarak Tuz Gölü\'nün tabanına dökülmesiyle', 'Bölgedeki tüm şahitkaya ve mantarkayaların kırılarak kumların üzerine serilmesiyle', 'Karapınar ovasına denizden kanallarla tuzlu su getirilip kumların ıslatılmasıyla'], 'Karapınar Erozyon Önleme Sahası\'nda kamış rüzgâr kıranlar kurulmuş, akasya, iğde ve ayrık otu gibi kurakçıl bitkiler dikilerek rüzgâr hızı kesilmiş ve kumullar sabitlenmiştir.'),
  ('Mantarkayaların alt kısmındaki sap bölümünün dar, üst kısmındaki şapka bölümünün geniş kalmasında aşağıdaki etkenlerden hangileri birlikte rol oynar?', 'Rüzgârın iri kum tanelerini yalnızca yere yakın seviyede taşıyabilmesi ve kayacın alt-üst tabaka direnç farkı', ['Kayacın alt kısmının kireç taşından erimesi, üst kısmının ise traverten birikimiyle büyümesi', 'Gündüzleri kayanın üst kısmının genleşip alt kısmının sürekli buz tutarak parçalanması', 'Yağmur sularının yalnızca kayanın gövde kısmına çarpıp tepe kısmına hiç değmemesi'], 'Korrazyon (zımparalama) yapan iri kum taneleri yerden ortalama 1-1,5 m yüksekliğe kadar sıçrayabildiği için alt kesim daha çok aşınır; tabaka direnç farkı da bu şekillenmeyi belirginleştirir.'),
  ('Deniz kıyılarında (örneğin Patara, Belek, Şile ve Kilyos kumsalları gerisinde) kumulların oluşabilmesi için aşağıdakilerden hangisi gereklidir?', 'Dalgaların kıyıya bol kum yığması ve denizden karaya doğru esen rüzgârların kuruyan kumları iç kesime taşıması', ['Kıyıda yüksek ve dik falezlerin bulunması ve denizin hemen kıyı önünde çok derin olması', 'Bölgede yıllık yağış miktarının 2000 milimetrenin üzerinde ve kıyının gür ormanlarla kaplı olması', 'Akarsuların taşıdığı tüm alüvyonları kıyıya ulaşmadan önce polye içindeki düdenlere boşaltması'], 'Kıyı kumulları, sığ kıyılarda dalgaların biriktirdiği kumların güneşle kuruduktan sonra denizden karaya esen rüzgârlar tarafından iç kesimlere sürüklenmesiyle oluşur; yalnızca çöllere özgü değildir.'),
  ('Çin\'deki Sarı Irmak (Huang-Ho) havzasında çok geniş yer kaplayan lös depolarının tarımsal açıdan verimli olmasına karşın erozyona çok duyarlı olmasının nedeni nedir?', 'İnce taneli, mineralce zengin fakat gevşek ve tutturulmamış gözenekli bir yapıda olması', ['Tamamen iri çakıl ve keskin granit bloklarından oluşan sert bir çöl kaldırımı olması', 'Yüzeyinin kalın bir kaya tuzu kabuğuyla kaplı olup suyu hiç geçirmemesi', 'Yalnızca dik dağ zirvelerinde birkaç santimetre kalınlığında oluşabilmesi'], 'Lös depoları kalker ve çeşitli minerallerce zengin ince toz yığınları olduğundan verimli toprak oluşturur; ancak çimentosuz ve gevşek yapısı nedeniyle akarsu ve rüzgârla çok kolay aşınır.'),
  ('Fiziksel (mekanik) ufalanmanın kurak bölgelerde rüzgâr aşındırmasına dolaylı katkısı aşağıdakilerden hangisidir?', 'Günlük sıcaklık farklarıyla parçalanan kayaçların rüzgârın taşıyıp aşındırmada kullanacağı kum ve toz malzemesini hazırlaması', ['Gece ve gündüz arasındaki sıcaklık farkının havadaki nemi yoğunlaştırarak şiddetli yağış oluşturması', 'Kayaçların içindeki kalsiyum karbonatı eriterek yer altında geniş mağara ağları kurması', 'Çöl yüzeyindeki kumları eritip camlaştırarak rüzgârın hızını tamamen kesmesi'], 'Çöllerde yüksek günlük sıcaklık farkı (genleşme-büzülme) kayaçları mekanik olarak ufalayıp kum-toz haline getirir; rüzgâr bu hazır kırıntıları hem süpürür hem de korrazyon aracı olarak kullanır.'),
  ('Nevşehir-Ürgüp (Kapadokya) çevresindeki peribacaları ile çöl bölgelerindeki mantarkayalar görünüm olarak benzeşse de oluşumlarındaki temel dış kuvvet farkı nedir?', 'Peribacalarında sel suları ve akarsu aşındırması birincil etken iken, mantarkayalarda rüzgâr korrazyonu doğrudan belirleyicidir', ['Peribacaları kireç taşının kimyasal erimesiyle oluşurken, mantarkayalar buzul aşındırmasıyla oluşur', 'Peribacaları deniz dalgalarıyla oyulurken, mantarkayalar yer altı sularının çökelmesiyle büyür', 'Peribacaları rüzgâr biriktirme şekli iken, mantarkayalar karstik biriktirme şeklidir'], 'Öğrencilerin sık karıştırdığı bir nokta olarak peribacaları volkanik tüflerde sel sularının aşındırmasıyla (rüzgâr dolaylı/ikincil etkilidir) oluşur; mantarkayalar ise doğrudan rüzgâr aşındırma şeklidir.'),
  ('Nemli tropikal kuşakta (örneğin Güney Çin\'in Guilin bölgesi, Vietnam ve Küba\'da) yüksek sıcaklık ve bol yağış altında ileri derecede gelişen dik konik-kuleli karst topografyasına ne ad verilir?', 'Kule karstı', ['Barkanlı çöl karstı', 'Buzul altı sirk karstı', 'Tafoni kaldırımı'], 'Sıcak ve bol yağışlı nemli tropikal iklimlerde kimyasal çözünme çok hızlı ve derinlemesine gerçekleştiği için polye ve ovalar üzerinde dik yamaçlı kule ve koni karstı (mogote/fenglin) gelişir.'),
  ('Hırvatistan ve Slovenya\'nın yer aldığı Adriyatik kıyısındaki Dinar Alpleri\'nin dünya jeomorfoloji literatüründe özel bir yere sahip olmasının nedeni nedir?', '"Karst" teriminin ve dolin, uvala, polye gibi birçok temel kavramın ilk kez bu kireç taşı platosunda tanımlanmış olması', ['Dünyadaki en büyük barkan ve erg kumullarının bu dağ kuşağında yer alması', 'Yeryüzünde traverten oluşumunun yalnızca bu bölgedeki sıcak gayzerlerde görülmesi', 'Rüzgârın oluşturduğu en uzun yardang sırtlarının Adriyatik kıyısında uzanması'], 'Slovenya-İtalya-Hırvatistan uzanımındaki Kras (Almanca Karst) platosu, saf kalker yapısı ve tipik erime şekilleriyle karst jeomorfolojisine adını veren klasik sahadır.'),
  ('Rüzgârın taşıma gücü ile tanecik boyutu arasındaki ilişki dikkate alındığında, şiddetli bir çöl fırtınasından sonra kaynak sahadan en uzağa taşınarak çökelen malzeme hangisidir?', 'Lös oluşturan ince toz ve silt taneleri', ['Barkanları oluşturan iri kuvars kumları', 'Reg yüzeyini kaplayan köşeli çakıllar', 'Hamada üzerindeki büyük kaya blokları'], 'Rüzgâr çakıl ve blokları yerinden oynatamaz, kum tanelerini sıçrama ve sürüklenmeyle kısa-orta mesafeye taşır; çok ince toz ve silt (lös) tanelerini ise asılı halde yüzlerce kilometre uzağa taşıyabilir.'),
  ('Orta Asya çöllerinden esen rüzgârların taşıdığı tozların Çin\'in doğusunda kalın lös platoları oluştururken çölün merkezinde hamada bırakması hangi süreci kanıtlar?', 'Rüzgârın tanecik boyutuna göre seçici aşındırma (deflasyon) ve mesafeye bağlı boylanma (biriktirme) yaptığını', ['Çöl merkezinde kimyasal çözünmenin, çöl çevresinde ise buzul aşındırmasının hakim olduğunu', 'Lös depolarının yalnızca deniz tabanında çökelip tektonik yükselmeyle karaya çıktığını', 'Hamada yüzeylerinin rüzgâr biriktirmesiyle, lös platolarının ise rüzgâr aşındırmasıyla oluştuğunu'], 'Rüzgâr kaynak alanda ince malzemeyi süpürüp (deflasyon) geride kayalık hamada bırakır; havalandırdığı kumları yakında kumul olarak, en ince tozları ise en uzakta lös olarak biriktirir.'),
  ('Denizli Acıpayam ve Burdur Tefenni polyelerinin tabanlarında kırmızı renkli terra rossa ile taşınmış alüvyonların karışık bulunmasının tarımsal sonucu nedir?', 'Normalde kireçli ve su tutması düşük olan karstik plato yüzeylerine kıyasla polye tabanlarının verimli tarım alanlarına dönüşmesi', ['Toprağın tamamen tuzlanarak hiçbir kültür bitkisinin yetişemeyeceği çorak bir çöl haline gelmesi', 'Ova tabanında birkaç yıl içinde hareketli barkan kumullarının oluşması', 'Yüzeydeki toprağın aniden çözünerek tüm ovanın dev bir obruğa dönüşmesi'], 'Karstik platoların çıplak kayalık yamaçlarından yıkanıp polye tabanına taşınan terra rossa ve akarsu alüvyonları kalın ve verimli bir tarım toprağı oluşturur.'),
  ('Bir bölgede gündüz sıcaklığın 45 °C\'ye çıkıp gece 2 °C\'ye düşmesi ile rüzgâr şekillerinin gelişimi arasında nasıl bir neden-sonuç bağı vardır?', 'Yüksek günlük sıcaklık farkı kayaçları fiziksel olarak ufalayarak rüzgârın aşındırma ve biriktirmede kullanacağı kırıntılı malzemeyi üretir', ['Gece sıcaklığın düşmesi havadaki karbondioksidi dondurarak kalker kayacında sarkıt oluşumunu hızlandırır', 'Gündüz sıcaklığın artması rüzgâr hızını sıfırlayarak tüm barkanların yerinde sabitlenmesini sağlar', 'Sıcaklık farkı yalnızca yer altı mağaralarının içindeki traverten basamaklarını parçalayarak lös üretir'], 'Kurak bölgelerde nem azlığı nedeniyle oluşan yüksek günlük sıcaklık farkı mekanik çözülmeyi şiddetlendirir; böylece rüzgârın kolayca taşıyabileceği bol kum ve toz ortaya çıkar.'),
  ('Harita üzerinde Sinop Sarıkum, İstanbul Terkos (Durusu) doğusu, Sakarya Karasu ve Adana Akyatan çevresini inceleyen bir araştırmacı hangi ortak yer şeklini gözlemler?', 'Kıyı kumullarını', ['Karstik polye ovalarını', 'Jips obruklarını', 'Yardang sırtlarını'], 'Karadeniz, Marmara ve Akdeniz\'in alçak kıyı ovaları ve lagünleri gerisinde (Sarıkum, Terkos, Karasu, Akyatan, Patara) dalga ve rüzgâr iş birliğiyle gelişmiş kıyı kumulları yer alır.'),
  ('Kıyı kumullarının çöl içlerindeki kumullardan ayrılan en belirgin coğrafi özelliği aşağıdakilerden hangisidir?', 'Nemli iklim bölgelerinin alçak kıyılarında da dalgaların getirdiği kumların deniz rüzgârlarıyla taşınmasıyla oluşabilmeleri', ['Yalnızca kalsiyum bikarbonatın suda kimyasal olarak çökelmesiyle meydana gelmeleri', 'Hiçbir zaman bitki örtüsüyle sabitlenemeyip sürekli denize doğru geri gitmeleri', 'Sadece kireç taşı falezlerinin tavan çökmesi sonucunda ortaya çıkmaları'], 'Çöl kumulları kurak iklimin doğrudan ürünüyken, kıyı kumulları Karadeniz gibi nemli iklim kıyılarında bile bol kum beslenmesi ve denizden esen rüzgârlar sayesinde oluşabilir.'),
  ('Alanya\'daki Dim Mağarası ile Damlataş Mağarası\'nın yıl boyunca iç sıcaklıklarının dış ortamdan çok daha az değişmesi (yaklaşık 18-22 °C civarında kalması) neyin sonucudur?', 'Kalın kireç taşı kütlesinin mağara içi atmosferini dışarıdaki mevsimlik ve günlük sıcaklık oynamalarından yalıtmasının', ['Mağara tabanından her mevsim sıcak volkanik lav sızıntılarının gelmesinin', 'İçeride esen şiddetli çöl rüzgârlarının mağara duvarlarını sürtünmeyle ısıtmasının', 'Mağara ağzının deniz seviyesinin yüz metre altında bulunmasının'], 'Yer altındaki kapalı ve yarı kapalı karstik mağara boşlukları, üstteki kalın kaya örtüsünün yalıtım etkisi ve yüksek bağıl nem sayesinde yıl boyu durağan bir mikroiklime sahiptir.'),
  ('Aşağıdaki eşleştirmelerden hangisinde yer şekli ile Türkiye\'de görüldüğü karakteristik saha yanlış verilmiştir?', 'Barkan ve şahitkaya - Doğu Karadeniz kıyı kuşağı (Rize-Hopa)', ['Polye ovaları - Göller Yöresi ve Batı Toroslar (Elmalı-Kestel)', 'Jips karstı şekilleri - Yukarı Kızılırmak Bölümü (Sivas-Zara)', 'Obruk oluşumları - Konya Kapalı Havzası ve Taşeli Platosu'], 'Doğu Karadeniz kıyı kuşağı yıl boyu yağışlı ve gür ormanlarla kaplı olduğundan rüzgâr aşındırma ve çöl tipi barkan şekillerinin oluşmasına elverişli değildir.'),
  ('Tuz Gölü çevresi ve Karapınar yakınlarında hem obruk gibi karstik şekillerin hem de kumul ve deflasyon izleri gibi rüzgâr şekillerinin bir arada görülmesi nasıl açıklanır?', 'Yüzeyde yarı kurak iklim ve cılız bitki örtüsü rüzgârı etkili kılarken, derindeki gölsel kireç taşı tabakalarının yer altı sularınca çözülmesiyle', ['Rüzgârın taşıdığı kumların kireç taşını kimyasal olarak eritip obruk açmasıyla', 'Bölgede yazın ekvatoral yağışların, kışın ise kutup rüzgârlarının etkili olmasıyla', 'Obrukların rüzgâr aşındırmasıyla, kumulların ise mağara çökmesiyle oluşmasıyla'], 'Konya-Karapınar havzasında üstte kurak-yarı kurak bozkır koşulları rüzgâr erozyonu ve kumul gelişimine yol açarken, alt zemindeki Neojen yaşlı kalker tabakalarında yer altı suyu erimesiyle obruklar oluşur.'),
  ('Bir kayaç kütlesinin yüzeyinde tafonilerin (kovukların) özellikle belirli bir yöne bakan yamaçta yoğunlaşması aşağıdakilerden hangisiyle ilişkilidir?', 'Nem taşıyan rüzgâr yönü, güneşlenme-buharlaşma farkı ve kayaçtaki mineral-çatlak dağılımıyla', ['Kayaç yüzeyine yalnızca o yönden meteor taşlarının çarpmasıyla', 'Yer altı su tablasının kayanın tepe noktasından dışarı fışkırmasıyla', 'Buzul dillerinin kayayı yalnızca güney yamacından törpülemesiyle'], 'Tafoniler, tuzlu veya nemli havanın kayayı ıslatması ve gölgede/güneşte farklı hızda buharlaşma sonucu tuz kristallenmesiyle parçalanan oyukların rüzgârla boşaltılmasıyla belirli bakılarda yoğunlaşır.'),
  ('Karstik arazilerde gelişen kanyon vadilerin yamaçlarının V profilli yatık vadiler yerine çok dik ve basamaklı duvarlar halinde inmesinin temel nedeni nedir?', 'Kalın tabakalı kalkerin mekanik olarak sağlam olması ve suyun yüzeysel yamaç aşındırmasından çok derine doğru çatlakları izleyerek kazması', ['Bölgede rüzgârların vadi yamaçlarını her iki yandan kumla dikleştirmesi', 'Vadi tabanından geçen akarsuyun hiç alüvyon taşımayıp yalnızca buz kütleleri sürüklemesi', 'Kalker kayacının yağmur suyuyla temas ettiğinde şişerek yükselmesi'], 'Kalın ve saf kireç taşlarında yağış suları yüzeysel akışla yamaçları yatıklaştıramadan çatlaklardan sızar; ana akarsu ve mağara tavanı çökmeleri yatağı hızla derine kazdığı için dik duvarlı kanyonlar oluşur.'),
  ('Antalya\'nın kuzeyindeki Kırkgöz kaynaklarından çıkan kireçli suların oluşturduğu, Düden Çayı\'nın da üzerinden geçerek Akdeniz\'e döküldüğü yer şekli hangisidir?', 'Antalya Traverten Platosu', ['Elmalı Polye Ovası', 'Karapınar Kumul Alanı', 'Silifke Deltası'], 'Kırkgöz karstik kaynaklarından beslenen suların çökerttiği kalsiyum karbonat tabakaları, deniz altında dahi basamakları devam eden dev Antalya Traverten Platosu\'nu oluşturmuştur.'),
  ('Rüzgârın taşıdığı ince kum tanelerinin çöl zemininde zıplayarak ilerlemesi hareketine jeomorfolojide ne ad verilir?', 'Saltasyon (sıçrama)', ['Süblimleşme (uçma)', 'Karstifikasyon (erime)', 'Sedimantasyon (taşlaşma)'], 'Rüzgârla taşınmada en ince tozlar süspansiyon (asılı kalma), orta boy kumlar saltasyon (sıçrama), iri kumlar ise sürüklenme (reptasyon) yoluyla hareket eder.'),
  ('Saltasyon (sıçrama) hareketiyle taşınan kum tanelerinin yerden genellikle 1-2 metreden daha yükseğe çıkamaması hangi yer şeklinin morfolojisini doğrudan belirler?', 'Mantarkayaların alt sap kısmının incelip üst kısmının geniş kalmasını', ['Polye ovalarının kenarlarında dik fay basamaklarının oluşmasını', 'Barkan kumullarının yüzlerce metre yüksekliğe ulaşmasını', 'Mağara tavanlarında sarkıtların dikitlerden daha uzun olmasını'], 'Sıçrayarak ilerleyen iri ve aşındırıcı kum taneleri yerden en fazla 1-2 metre yüksekliğe erişebildiği için kayaların taban kısmını yoğun biçimde oyar ve mantarkaya görünümü ortaya çıkar.'),
  ('Bir bölgede arazi çalışması yapan öğrenciler; keskin oluklu kayalar, kızıl renkli killi toprak cepleri, maki çalılıkları ve su yutan kuyular gözlemlemiştir. Bu arazi Türkiye\'de büyük olasılıkla nerededir?', 'Teke veya Taşeli Platosu\'nda', ['Ergene Havzası\'nın orta kesiminde', 'Çarşamba Deltası\'nın kıyı şeridinde', 'Ardahan-Kars lav platosunda'], 'Keskin oluklu kayalar (lapya), kızıl toprak (terra rossa), maki bitki örtüsü ve suyutan (düden) kuyuları Akdeniz Bölgesi\'ndeki Teke ve Taşeli karstik platolarının tipik özellikleridir.'),
  ('Mağara turizmi açısından büyük önem taşıyan sarkıt, dikit ve sütun gibi şekillerin ortak adı aşağıdakilerden hangisidir?', 'Damlataş (speleotem) şekilleri', ['Deflasyon (süpürme) çukurları', 'Korrazyon (zımparalama) sırtları', 'Abrazyon (dalga) platformları'], 'Mağara boşluklarında sızan ve damlayan kireçli suların kalsiyum karbonat çökeltmesiyle oluşturduğu sarkıt, dikit, sütun ve perde travertenlerin tamamına damlataş (speleotem) adı verilir.'),
  ('Yüksek dağ kuşaklarındaki buzul çevresi (periglasiyal) alanlarda da çöllere benzer biçimde geniş lös depolarının oluşabilmesi neyle açıklanır?', 'Buzulların öğüttüğü ince kaya ununun (mili) bitki örtüsünden yoksun buzul önü düzlüklerinden rüzgârlarla taşınarak biriktirilmesiyle', ['Buzul kütlelerinin kireç taşını eriterek sarı renkli terra rossa toprağı üretmesiyle', 'Kutup bölgelerinde günlük sıcaklık farkının 50 derecenin üzerine çıkmasıyla', 'Buzulların erimesiyle oluşan göllerde bol miktarda traverten çökelmesiyle'], 'Kuzey Amerika ve Avrupa\'daki geniş lös kuşaklarının önemli bir kısmı, Kuvaterner buzullarının öğüttüğü ince toz-mil malzemesinin buzul önü (sandur) düzlüklerinden rüzgârlarla taşınmasıyla oluşmuştur.'),
  ('Karstik bir arazide yer altı mağara ağının uzanış yönünü ve yer altı suyunun hangi voklüz kaynağından çıktığını belirlemek isteyen hidrojeologlar hangi yöntemi uygular?', 'Düdenlerden suya zararsız izleyici boya (floresein vb.) bırakarak çevredeki kaynaklardan çıkışını ve süresini takip etmek', ['Mağara üzerindeki tepeye rüzgâr ölçer yerleştirerek barkanların ilerleme hızını hesaplamak', 'Polye tabanındaki toprağı kazarak içindeki kuvars kumu oranını ölçmek', 'Yamaçtaki lapya oluklarının derinliğini cetvelle ölçüp ortalamasını almak'], 'Karst hidrojeolojisinde suyutan (düden) ile suçıkan (voklüz) arasındaki yer altı bağlantısını saptamak için suya çevreye zararsız renklendirici veya izleyici maddeler katılarak kaynaklar gözlemlenir.'),
  ('Van Gölü\'nün kuzeyinde ve Ağrı Dağı eteklerinde kurak yaz dönemlerinde yerel toz fırtınaları yaşanmasına rağmen Büyük Sahra\'daki gibi dev erg kumullarının gelişmemesinin temel nedeni nedir?', 'Yıllık yağışın yarı nemli-step sınırında olması, kışın kar örtüsünün zemini koruması ve engebeli topografyanın geniş kumul birikimini sınırlaması', ['Bölgede rüzgâr hızının yıl boyunca kum tanelerini hareket ettiremeyecek kadar düşük olması', 'Arazinin tamamen saf kalker ve kaya tuzu tabakalarıyla kaplı olması', 'Van Gölü sularının çevredeki tüm kumları kimyasal olarak eritmesi'], 'Doğu ve İç Anadolu\'da mevsimlik yağışlar, kış kar örtüsü ve step bitki örtüsü tam çöl koşullarının oluşmasını engeller; bu nedenle rüzgâr şekilleri Büyük Sahra ölçeğine ulaşamaz.'),
  ('Bir obruğun oluşum yaşı bakımından "genç" ya da "eski (olgun)" olduğu yamaç morfolojisine bakılarak nasıl ayırt edilir?', 'Genç obrukların duvarları çok dik ve keskin kenarlı iken, eski obruklarda yamaçların aşınıp yıkılmasıyla eğim azalmış ve tabanda enkaz birikmiştir', ['Genç obrukların tabanında her zaman kalın lös depoları bulunurken, eski obruklar tamamen buzla doludur', 'Genç obruklar yatay tünel biçimindeyken, eski obruklar mantarkaya gibi yerden yükselir', 'Genç obruklar yalnızca granit kayada, eski obruklar ise yalnızca bazalt kayada görülür'], 'Yeni çökmüş obruklar (örneğin Karapınar\'da yeni açılanlar) silindirik ve dik duvarlıdır; binlerce yıllık eski obruklarda (örneğin Kızören veya Cennet çöküğü) yamaç gerilemesiyle ağız genişler ve yamaç eğimi yatıklaşır.'),
  ('Jips (alçı taşı) ile kalker (kireç taşı) üzerindeki karstlaşma karşılaştırıldığında suyun kimyasal bileşimi açısından hangi temel fark ortaya çıkar?', 'Kalkerin etkili çözünmesi için suda çözünmüş karbondioksit (karbonik asit) gerekirken, jips saf suda bile doğrudan ve hızla çözünebilir', ['Jips yalnızca tuzlu deniz suyunda çözünürken, kalker yalnızca sıcak volkanik sularda çözünür', 'Kalker çözündüğünde geriye kuvars kumu kalırken, jips çözündüğünde bazalt çakılı kalır', 'Jipsin çözünmesi için sıcaklığın sıfır derecenin altında olması şarttır'], 'CaCO3 (kalker) saf suda çok az çözünür ve karstlaşma için CO2\'li suya ihtiyaç duyar; CaSO4·2H2O (jips) ve NaCl (kaya tuzu) ise karbondioksit olmasa bile saf suda doğrudan ve çok daha hızlı çözünür.'),
  ('Isparta\'nın Aksu ilçesi yakınlarında bulunan, içinden yer altı deresi akan ve zengin damlataş oluşumlarına sahip karstik mağara hangisidir?', 'Zindan Mağarası', ['Tuz Mağarası', 'Buzluk Mağarası', 'Yarımburgaz Mağarası'], 'Isparta Aksu\'daki Zindan Mağarası, Köprüçay\'ın kollarından birinin kireç taşını oymasıyla gelişmiş uzun ve aktif bir karstik mağaradır.'),
  ('Harput (Elazığ) ve Ağrı Doğubayazıt yakınlarında bulunan "Buzluk Mağarası" adlı oluşumlarda yaz aylarında dahi buz sarkıtlarının görülmesi neyle ilgilidir?', 'Mağara içi hava dolaşımı, derinlik-basınç farkı ve buharlaşma soğuması nedeniyle içerideki sıcaklığın donma noktasında kalmasıyla', ['Mağaraların deniz seviyesinden 6000 metre yüksekteki kalıcı buzul kuşağında yer almasıyla', 'İçerideki kaya tuzu tabakalarının suyla birleşince kendiliğinden buza dönüşmesiyle', 'Çöl rüzgârlarının mağara içine kıştan kalan barkan kumlarını yığmasıyla'], 'Bazı karstik ve kayaç çöküntü mağaralarında (örneğin Elazığ Harput Buzluk Mağarası) kışın içeri çöken soğuk havanın hapsolması ve yazın hava akımı-buharlaşma termodinamiği sayesinde doğal buz oluşumu görülür.'),
  ('Rüzgâr erozyonuna maruz kalan yarı kurak tarım alanlarında toprağın nadasa bırakılıp bitkisiz tutulması ve anız yakılması hangi sonucu doğurur?', 'Toprak agregatlarını tutan organik maddeyi yok ederek rüzgâr deflasyonunu ve toz fırtınalarını şiddetlendirir', ['Toprak yüzeyinde koruyucu bir traverten tabakası oluşturarak su kaybını önler', 'Yağmur sularının yer altına sızmasını hızlandırarak polye oluşumunu başlatır', 'Rüzgârın taşıdığı kumları tarlada tutarak çernozyom toprağı üretir'], 'Anız yakılması ve kuru toprağın ufalanarak çıplak bırakılması yüzey pürüzlülüğünü ve kök bağlarını ortadan kaldırır; bunun sonucunda rüzgâr en verimli üst toprağı kolayca süpürür.'),
  ('Bir jeomorfolog çölde yaptığı ölçümde hakim rüzgârın sürekli kuzeybatıdan güneydoğuya doğru estiğini saptamıştır. Bu sahadaki tipik bir barkanın sivri uçları (boynuzları) hangi yönü gösterir?', 'Güneydoğuyu', ['Kuzeybatıyı', 'Kuzeydoğuyu', 'Güneybatıyı'], 'Barkanların az eğimli dışbükey sırtı rüzgârın geldiği yöne (kuzeybatıya) bakar; kumulun daha hızlı ilerleyen iki sivri ucu ise rüzgârın gittiği yön olan güneydoğuyu gösterir.'),
  ('Antalya\'daki Düden Şelalesi\'nin (Aşağı Düden) sularını yaklaşık 40 metrelik bir falez üzerinden doğrudan Akdeniz\'e dökmesi hangi iki yer şekli sürecinin kesişimini gösterir?', 'Karstik traverten platosu kenarının deniz dalgalarıyla aşındırılarak falezleştirilmesi ve karstik akarsuyun buradan dökülmesi', ['Rüzgârın oluşturduğu şahitkayanın buzul vadisi tarafından ortadan ikiye yarılması', 'Tektonik bir obruk gölünün çöl rüzgârlarıyla denize doğru taşırılması', 'Akarsuyun taşıdığı kumların kıyıda dev bir barkan seti oluşturması'], 'Antalya\'da kalın traverten basamaklarının denize ulaştığı kıyı çizgisinde dalga aşındırması dik traverten falezleri oluşturmuş, karstik Düden Çayı da bu falezden şelale yaparak denize kavuşmuştur.'),
  ('Bir öğrenci proje ödevinde yer şekillerini "Kimyasal Çözünme Etkili Olanlar" ve "Mekanik Aşındırma/Biriktirme Etkili Olanlar" diye iki tabloya ayıracaktır. Hangi eşleştirme tamamen doğrudur?', 'Kimyasal: Uvala ve Lapya — Mekanik (Rüzgâr): Yardang ve Barkan', ['Kimyasal: Mantarkaya ve Lös — Mekanik (Rüzgâr): Polye ve Sarkıt', 'Kimyasal: Hamada ve Şahitkaya — Mekanik (Rüzgâr): Dolin ve Dikit', 'Kimyasal: Barkan ve Tafoni — Mekanik (Rüzgâr): Traverten ve Obruk'], 'Uvala ve lapya suyun kalkeri kimyasal olarak çözmesiyle oluşurken; yardang rüzgârın mekanik aşındırması, barkan ise rüzgârın mekanik biriktirmesiyle meydana gelir.'),
  ('Muğla Ovası\'nın kenarlarında dik yamaçların bulunması, tabanının düz olması ve yağışlı dönemlerde sularını "Akyaka-Gökova" yönündeki yer altı yollarına ileten düdenlere sahip olması onun hangi yer şekli olduğunu gösterir?', 'Karstik polye ovası', ['Kıyı delta ovası', 'Volkanik krater düzlüğü', 'Rüzgâr hamada yüzeyi'], 'Muğla Ovası, Batı Toros-Menteşe geçişinde kalker kütleleri içinde tektonik ve karstik süreçlerle gelişmiş, drenajını düdenlerle sağlayan tipik bir polye (gölova) örneğidir.'),
  ('Kurak bir bölgede yatay uzanışlı tortul kayaç serisi içinde üstte çok sert silisli kireç taşı, altta ise gevşek kil ve kum taşı ardalanması bulunuyorsa rüzgâr ve sel aşındırmasıyla hangi şeklin gelişmesi beklenir?', 'Üstteki sert tabakanın koruyucu şapka görevi yaptığı şahitkaya (masa tepe) şekillerinin', ['Yüzeyde kirecin çökelmesiyle büyüyen beyaz traverten taraçalarının', 'Rüzgâr yönüne dik uzanan hilal biçimli hareketli barkan kumullarının', 'Yer altı suyunun yüzeye çıktığı gür voklüz kaynaklarının'], 'Yatay tortul yapıda üstteki dirençli tabaka alttaki yumuşak katmanları korur; çevredeki dirençsiz kısımlar aşınıp süpürüldüğünde üstü düz şahitkayalar (butte/mesa benzeri tepeler) ortaya çıkar.'),
  ('Karstik mağaraların turizme açılması sürecinde içeride yüksek ısı yayan güçlü aydınlatma ampullerinin kullanılması ve ziyaretçi sayısının sınırlandırılmaması hangi bozulmaya yol açar?', 'Mağara içi sıcaklığı ve karbondioksit dengesini bozarak damlataş gelişimini durdurur ve nemli yüzeylerde yosunlaşmaya (lamba florasına) neden olur', ['Mağara tavanındaki kireç taşını bir ay içinde eriterek mağarayı açık bir polye ovasına dönüştürür', 'İçeride şiddetli rüzgâr akımı başlatarak sarkıtları mantarkayaya çevirir', 'Mağara tabanındaki tüm suları dondurarak kalıcı buzul sirki oluşturur'], 'Mağara ekosistemi çok hassastır; aşırı insan solunumu CO2 oranını ve sıcaklığı artırır, yanlış ışıklandırma ise sarkıt ve dikitlerin üzerinde yeşil alg-yosun (lampenflora) üreyerek kararmasına yol açar.'),
  ('Güneydoğu Anadolu\'nun güney kesimlerinde (Harran, Ceylanpınar ve Mardin kızıltepe ovalarında) yaz aylarında güneyden esen sıcak rüzgârların tarım ve yaşam üzerindeki jeomorfolojik etkisi nedir?', 'Suriye çöl kuşağından ince toz ve mil (lös benzeri partikül) taşıması ve kuruyan çıplak tarlalarda rüzgâr erozyonuna yol açması', ['Fırat Nehri\'nin yatağını değiştirerek bölgede derin buzul vadileri açması', 'Ovaların tamamını birkaç metre kalınlığında beyaz traverten kabuğuyla örtmesi', 'Bazalt kayalarını kimyasal olarak eriterek bölgede yüzlerce obruk gölü oluşturması'], 'Suriye çölüne komşu olan Güneydoğu Anadolu düzlüklerinde samyeli karakterli rüzgârlar yaz kuraklığında hem ince toz taşınımına hem de bitkisiz tarlalarda deflasyona neden olur.'),
  ('Karstik bir yörede yağış miktarı yeterli olmasına rağmen tarlada sulama suyu sıkıntısı çekilmesi ve köylerin belirli kaynak başlarında toplanması hangi faktörle açıklanır?', 'Geçirgen kalker zeminin yüzey sularını yer altına kaçırması nedeniyle akarsu ağının cılız kalmasıyla', ['Bölgede rüzgârların tüm yağmur bulutlarını yağış bırakmadan dağıtmasıyla', 'Toprağın aşırı killi ve geçirimsiz olup suyu yüzeyde tuzlandırmasıyla', 'Köylülerin tarım yerine yalnızca kıyı balıkçılığıyla uğraşmasıyla'], 'Karstik platolarda yağış az olmasa bile "hidrolojik kuraklık" (yüzeyde su tutulamaması) yaşanır; bu nedenle kırsal yerleşmeler voklüz kaynaklarının ve su tutan polye tabanlarının çevresinde toplanır.'),
  ('Bir kumul sahasında kum tepelerinin üzerine doğal çalı ve otların yerleşmeye başlaması kumulun dinamik durumu hakkında neyi ifade eder?', 'Rüzgârın taşıma etkisinin azaldığını (veya nemin arttığını) ve hareketli "canlı" kumulun "sabit (fosil)" kumula dönüşmeye başladığını', ['Kumulun ilerleme hızının iki katına çıkarak barkan şeklini aldığını', 'Kum tanelerinin altında büyük bir yer altı mağarasının çökmek üzere olduğunu', 'Bölgede yıllık yağış miktarının sıfıra düştüğünü ve hamada oluştuğunu'], 'Bitki örtüsünden yoksun ve sürekli yer değiştiren kumullara aktif (hareketli) kumul, bitkilendirme veya iklimin nemlenmesiyle hareketi duran kumullara ise sabitlenmiş (ölü/fosil) kumul denir.'),
  ('Aşağıdaki yer şekli çiftlerinden hangisinin oluşumunda aynı dış kuvvet etkili olmuştur?', 'Şahitkaya ve Barkan', ['Polye ve Yardang', 'Mantarkaya ve Obruk', 'Traverten ve Lös'], 'Şahitkaya rüzgâr aşındırma, barkan ise rüzgâr biriktirme şekli olup her ikisinin de temel oluşturucu dış kuvveti rüzgârdır.'),
  ('Moren depolarını akarsu alüvyonlarından ayıran en belirgin yapısal özellik aşağıdakilerden hangisidir?', 'Malzemelerin boylanmamış ve köşeli olması', ['Yalnızca ince mil ve kilden oluşması', 'Belirgin yatay tabakalaşma göstermesi', 'Yuvarlaklaşmış çakılların üstte toplanması'], 'Buzullar katı halde taşıma yaptığı için morenlerdeki malzemeler aşınıp yuvarlaklaşmaz ve büyüklüklerine göre ayrılmaz.'),
  ('Sander düzlüklerindeki tortulların moren yığınlarına kıyasla daha yuvarlak ve boylanmış olmasının temel nedeni nedir?', 'Erime sularının akarsu karakterinde taşıma ve biriktirme yapması', ['Buzul kütlesinin ağırlığıyla taşları un haline getirmesi', 'Rüzgarların buzul önündeki ince kumları savurması', 'Deniz dalgalarının buzul cephesini sürekli yıkaması'], 'Sander düzlükleri buzuldan çıkan erime suları tarafından oluşturulduğu için akarsu biriktirmesine özgü boylanma görülür.'),
  ('Bir hörgüçkayanın buzula bakan yamacı ile buzulun ilerlediği yöndeki yamacı karşılaştırıldığında nasıl bir fark görülür?', 'Buzulun geldiği yamaç az eğimli ve cilalı, gittiği yamaç dik ve pürüzlüdür', ['Her iki yamaç da simetrik ve eşit eğimlidir', 'Buzulun geldiği yamaç sarp uçurumlu, gittiği yamaç tatlı eğimlidir', 'Üst kısmı düzleşmiş, yan yamaçları dikey çatlaklarla yarılmıştır'], 'Buzul kayaya tırmanırken törpüleme ile pürüzsüzleştirir, aşarken koparma (plucking) yaptığı için arka yamacı dikleştirir.'),
  ('Haritada kıyı çizgisine çok yakın bir adanın zamanla anakaraya bağlanarak yarımadaya dönüştüğü gözlenmiştir. Bu süreçte aşağıdaki koşullardan hangisinin gerçekleştiği savunulabilir?', 'Ada ile kıyı arasındaki sığ alanda dalga kırılması ve kum birikiminin arttığı', ['Deniz seviyesinin hızla yükselerek kıyı ovalarını sular altında bıraktığı', 'Güçlü gelgit akıntılarının kıyıdaki kumulları açık denize süpürdüğü', 'Kıyı boyunca aktif fayların çökme hareketi oluşturduğu'], 'Ada arkasında dalga enerjisinin azalmasıyla kumlar birikir ve kıyı oku adayı karaya bağlayarak tombolo oluşturur.'),
  ('Antalya\'nın doğusu ile batısı karşılaştırıldığında Finike-Kaş arasında falezler yaygınken, Serik-Manavgat kıyılarında geniş kumsalların görülmesi neyle açıklanır?', 'Dağların kıyı çizgisine olan uzaklığının ve kıta sahanlığı genişliğinin değişmesiyle', ['Deniz suyu tuzluluk ve sıcaklık değerlerinin kısa mesafede farklılaşmasıyla', 'Batı kesimde gelgit genliğinin doğu kesime göre çok yüksek olmasıyla', 'Hakim rüzgar yönünün batıda karadan denize doğru esmesiyle'], 'Dağların kıyıya hemen kavuştuğu Kaş çevresinde şelf dardır ve falez oluşur; kıyı düzlüğünün genişlediği yerde plaj gelişir.'),
  ('Drumlin tepelerinin uzanış doğrultusu incelenerek bir bölgenin geçmişteki doğal ortamı hakkında hangi bilgiye doğrudan ulaşılabilir?', 'Örtü buzullarının ilerleme yönüne', ['Yıllık ortalama yağış miktarına', 'Deniz seviyesindeki alçalma hızına', 'Kayaçların kimyasal çözünme derecesine'], 'Drumlinlerin dik ucu buzulun geldiği yönü, alçalarak uzanan kuyruk kısmı ise buzulun ilerlediği yönü gösterir.'),
  ('Doğu Karadeniz ve Batı Karadeniz kıyılarında falezlerin çok yaygın olmasına karşın Orta Karadeniz\'de (Samsun çevresi) falezlerin azalıp kıyı okları ile lagünlerin görülmesinin ana sebebi nedir?', 'Canik Dağları\'nın geride ve alçak uzanması nedeniyle kıta sahanlığının genişlemesi', ['Kızılırmak ve Yeşilırmak\'ın taşıdığı suların deniz tuzluluğunu azaltması', 'Orta Karadeniz\'de kuzey sektörlü rüzgarların etkisini kaybetmesi', 'Karadeniz\'deki dip akıntılarının yalnızca orta kesimde yüzeye çıkması'], 'Samsun çevresinde dağlar kıyıdan içeride kaldığı ve büyük deltalar geliştiği için kıyı sığlaşmış, birikim şekilleri öne çıkmıştır.'),
  ('Asılı vadilerin ana buzul vadisine kavuştuğu basamaklı yamaçlarda buzulların çekilmesinden sonra yaygın olarak hangi doğal oluşum gözlenir?', 'Çağlayan ve şelaleler', ['Lagün gölleri', 'Kıyı kordonları', 'Barkan kumulları'], 'Yüksekte kalan asılı vadilerden ana vadiye inen akarsular dik yamaç basamağından dökülerek şelaleler oluşturur.'),
  ('2200 metre yüksekliğindeki Uludağ\'ın zirve kesiminde sirk göllerine rastlanırken, 1000 metre yüksekliğindeki Yıldız Dağları\'nda buzul şekillerine rastlanmaması hangi faktörle açıklanır?', 'Kalıcı kar ve buzullaşma sınırına ulaşacak yükselti farkıyla', ['Denize olan uzaklık ve karasallık şiddetiyle', 'Kayaçların geçirgenlik ve sertlik derecesiyle', 'Bakı etkisinin kuzey yamaçlarda değişmesiyle'], 'Kuaterner\'de Türkiye\'de kalıcı kar sınırı yaklaşık 2000-2200 metreye kadar indiği için daha alçak dağlar buzullaşmamıştır.'),
  ('Bir lagün gölünün zamanla tatlı su özelliğine kavuşabilmesi için aşağıdakilerden hangisinin gerçekleşmesi gerekir?', 'Denizle bağlantısının tamamen kesilmesi ve göle tatlı su kaynaklarının dökülmesi', ['Kıyı kordonunun fırtına dalgalarıyla parçalanarak açık denize açılması', 'Buharlaşma şiddetinin gölü besleyen yağış miktarından fazla olması', 'Gelgit akıntılarının günde iki kez göl içerisine deniz suyu taşıması'], 'Denizle irtibat kesilip akarsular ve yağışlarla beslenme sürerse gölün tuzluluğu zamanla azalır; Terkos Gölü buna örnektir.'),
  ('Yan morenler ile cephe morenlerinin oluşum yerleri arasındaki temel fark aşağıdakilerden hangisidir?', 'Yan morenler buzul vadisinin yamaçları boyunca, cephe morenleri buzulun eriyip sonlandığı uç kısımda birikir', ['Yan morenler deniz tabanında, cephe morenleri yüksek zirvelerdeki sirklerde birikir', 'Yan morenler ince killerden, cephe morenleri yalnızca volkanik küllerden oluşur', 'Yan morenler rüzgar etkisiyle, cephe morenleri dalga etkisiyle taşınır'], 'Vadi buzulunun iki kenarı boyunca taşınan enkaz yan moreni, buzul dilinin eridiği en ileri sınırda yığılan kavisli sırtlar cephe morenini oluşturur.'),
  ('Çukurova Deltası\'nın kıyılarında Akyatan ve Yumurtalık gibi lagün göllerinin gelişmiş olması aşağıdakilerden hangisini kanıtlar?', 'Akarsu biriktirmesiyle sığlaşan kıyılarda dalga ve akıntı biriktirmesinin de etkili olduğunu', ['Kıyı kesiminde epirojenezle hızlı bir çökmenin devam ettiğini', 'Gelgit genliğinin Akdeniz kıyılarında yüksek değerlere ulaştığını', 'Falez gerilemesinin delta ovasını hızla daralttığını'], 'Deltaların denize doğru ilerlediği sığ kıyılarda dalga ve kıyı akıntıları kum kordonları oluşturarak lagünleri meydana getirir.'),
  ('İki komşu vadi buzulunun yan yana uzanan sirklerini ve vadilerini geriye doğru aşındırması sonucunda aralarında kalan keskin ve sarp sırtlara ne ad verilir?', 'Aret', ['Drumlin', 'Sander', 'Abrazyon düzlüğü'], 'Komşu sirklerin ve buzul vadilerinin yamaçlarını kemirmesiyle aradaki bölme incelip bıçak sırtı gibi keskinleşerek aretleri oluşturur.'),
  ('Bir dağ kütlesinin üç veya daha fazla yamacındaki sirklerin geriye doğru aşınarak zirveyi sarp ve piramidal bir tepeye dönüştürmesiyle oluşan şekil hangisidir?', 'Buzul boynuzu', ['Hörgüçkaya', 'Moren seti', 'Kıyı oku'], 'Alpler\'deki Matterhorn tepesi gibi piramidal zirveler (horn), birden fazla sirkin geriye aşındırmasıyla oluşur.'),
  ('Falezlerin alt kısmında dalgaların çarpmasıyla oluşan oyukların (abrazyon hücresi) derinleşmesi kıyı çizgisinde nasıl bir değişime yol açar?', 'Üstteki kaya kütlesinin çökmesiyle falezin kara içine doğru gerilemesine', ['Kıyı önündeki denizin hızla derinleşerek hendek oluşturmasına', 'Falez yamacının tatlı eğimli bir kumul tepesine dönüşmesine', 'Kıyı okunun doğrudan falez duvarına dik açıyla bağlanmasına'], 'Dalga aşındırmasıyla altı oyulan dik yamaç desteğini kaybedip çöker; böylece falez geriler ve önünde abrazyon platformu genişler.'),
  ('Aydos Dağı (İstanbul - 537 m), Bozdağ (İzmir - 2159 m) ve Erciyes Dağı (Kayseri - 3917 m) kütlelerinden hangisinde hem güncel buzul hem de gelişmiş sirk ve moren şekilleri birlikte görülür?', 'Erciyes Dağı', ['Aydos Dağı', 'Bozdağ', 'Aydos ve Bozdağ'], 'Erciyes Dağı yaklaşık 4000 metreye yaklaşan yükseltisiyle hem eski buzul şekillerini hem de küçük güncel zirve buzulunu barındırır.'),
  ('Okyanus kıyılarında kıyı oku, lagün ve tombolo oluşumunun iç deniz kıyılarına göre daha zor gerçekleşmesinin temel nedeni nedir?', 'Güçlü gelgit ve okyanus akıntılarının kıyıdaki birikim malzemesini dağıtması', ['Okyanus sularının yoğunluğunun ve kaldırma kuvvetinin çok düşük olması', 'Okyanus kıyılarında kimyasal çözünmenin fiziksel ufalanmadan hızlı olması', 'Kıta sahanlığının tüm okyanus kıyılarında tamamen yok olması'], 'Yüksek gelgit genliği kıyı şeridinde biriken kum ve çakılları sürekli süpürerek kordon ve okların kalıcı olmasını engeller.'),
  ('İki vadi buzulunun birleştiği yerde, her iki buzulun iç kenarlarındaki yan morenlerin kaynaşarak tek bir şerit halinde taşınmasıyla oluşan moren türü hangisidir?', 'Orta moren', ['Taban moreni', 'Cephe moreni', 'Sander düzlüğü'], 'İki buzul kolu birleştiğinde birbirine komşu olan yan morenler birleşik buzulun ortasında uzanan orta moreni meydana getirir.'),
  ('Marmara Denizi\'nin güneyinde yer alan Kapıdağ Yarımadası\'nın karaya bağlandığı Belkıs kıstağında iki kıyı okunun gelişmiş olması neyin sonucudur?', 'Karşılıklı kıyı akıntılarının ve dalga kırınımının iki yandan kum biriktirmesinin', ['Bölgedeki volkanik lav akıntılarının denizi iki koldan doldurmasının', 'Gelgit sularının yarımada çevresinde derin kanallar açmasının', 'Akarsu taşkınlarının adanın merkezinden kıyıya çakıl yaymasının'], 'Kapıdağ Tombolosu çift kıyı okunun ada ile anakara arasında birleşip aradaki sığlığı doldurmasıyla gelişmiş tipik bir örnektir.'),
  ('Buzul vadilerinin önünün cephe morenleriyle kapanması ve gerideki çanağın erime sularıyla dolması sonucunda hangi göl türü oluşur?', 'Moren set gölü', ['Sirk gölü', 'Lagün gölü', 'Alüvyal set gölü'], 'Cephe morenlerinin doğal bir bent görevi görerek vadi önünü tıkamasıyla moren set gölleri meydana gelir.'),
  ('Bir araştırmacı kıyı boyunca yürüdüğünde çakıllı plajlar, kıyı okları ve koy ağzını kapatan kordonlar gözlemliyorsa bu kıyıda dalgaların hangi faaliyeti baskındır?', 'Biriktirme', ['Aşındırma', 'Çözündürme', 'Çökertme'], 'Plaj, kıyı oku ve kıyı kordonu dalga ve kıyı akıntılarının sığ kıyılarda yaptığı biriktirme şekilleridir.'),
  ('Kanada, İskandinavya ve Kuzey Avrupa düzlüklerinde binlerce gölün, geniş moren örtülerinin ve drumlin tarlalarının bulunması aşağıdakilerden hangisiyle doğrudan ilişkilidir?', 'Pleistocene döneminde geniş örtü buzullarının bu alanları kaplamasıyla', ['Şiddetli tektonik kırılmaların genç çöküntü hendekleri oluşturmasıyla', 'Muson yağmurlarının yüzeyi derin vadilerle parçalamasıyla', 'Kalkerli arazinin soğuk sularda hızla eriyerek obruklaşmasıyla'], 'Kuzey yarımkürenin yüksek enlemleri dördüncü jeolojik zamanda kalın kıta (örtü) buzulları altında kalmış ve zengin buzul topoğrafyası kazanmıştır.'),
  ('Abrazyon platformlarının deniz seviyesinden yüksekte basamaklar (kıyı taraçası) halinde görülmesi o kıyıda hangi iç kuvvet hareketinin yaşandığını gösterir?', 'Karanın epirojenezle yükseldiğini veya deniz seviyesinin alçaldığını', ['Buzulların kıyı çizgisine kadar ilerleyip geri çekildiğini', 'Volkanik küllerin kıyı şeridinde kalın tabakalar oluşturduğunu', 'Kıyı akıntılarının yön değiştirerek biriktirmeye geçtiğini'], 'Eski dalga aşınım düzlüklerinin su üstüne çıkarak taraça oluşturması karanın yükselmesi (regresyon) ile açıklanır.'),
  ('Büyükçekmece ve Küçükçekmece göllerinin Karadeniz kıyısındaki Terkos Gölü ile ortak oluşum mekanizması aşağıdakilerden hangisidir?', 'Kıyı kordonlarının koy ağızlarını kapatmasıyla oluşan lagünler olmaları', ['Tektonik çöküntü çukurlarının akarsularla dolmasıyla oluşmaları', 'Eski buzul vadilerinin deniz suları altında kalmasıyla gelişmeleri', 'Kireçtaşı tabakalarının çökmesiyle oluşan karstik göller olmaları'], 'Her üç göl de İstanbul kıyılarında dalga ve akıntı biriktirmesi sonucu koy önlerinin kapanmasıyla oluşmuş lagünlerdir.'),
  ('Bir kıyıda falezlerin önünde dar da olsa çakıllı bir kumsalın oluşmaya başlaması, kıyı gelişim sürecinde neyin değiştiğine işaret eder?', 'Falez gerilemesiyle genişleyen abrazyon düzlüğünün dalga enerjisini azaltarak birikime zemin hazırladığına', ['Kıta sahanlığının aniden daralarak okyanus hendeğine dönüştüğüne', 'Dalga aşındırmasının tamamen durup rüzgar aşındırmasının başladığına', 'Gelgit genliğinin birkaç kat artarak kıyıyı sular altında bıraktığına'], 'Falez geriledikçe önünde sığ bir abrazyon platformu genişler; dalgalar burada daha erken kırıldığı için aşındırma yavaşlar ve malzeme birikebilir.'),
  ('Buzul aşındırmasının akarsu aşındırmasından farklı olarak vadi tabanında ters eğimler ve çukurluklar oluşturabilmesinin nedeni nedir?', 'Katı haldeki kalın buzul kütlesinin yüksek basınçla tabanı oyup yokuş yukarı da ilerleyebilmesi', ['Buzulların yalnızca çözünebilen kireçtaşı ve jips tabakalarını eritmesi', 'Buzul altındaki suların yerçekiminden bağımsız hareket etmesi', 'Buzul vadilerinde rüzgarların girdap oluşturarak tabanı oyması'], 'Akarsular genel taban seviyesinin altına veya ters eğime kazamazken, kalın buzullar ağırlık ve plastik akışla aşırı derinleştirme yapabilir.'),
  ('Bafra ve Çarşamba ovalarının kıyı kesiminde Balık Gölü ve Simenlik Gölü gibi oluşumların yer alması hangi iki dış kuvvetin ortak etkisini yansıtır?', 'Akarsu ve dalga', ['Buzul ve rüzgar', 'Dalga ve buzul', 'Rüzgar ve yeraltı suyu'], 'Delta ovalarını akarsular oluştururken, delta kıyısındaki lagün göllerini dalga ve kıyı akıntılarının oluşturduğu kordonlar meydana getirir.'),
  ('Sinop Yarımadası\'nın kuzey kıyılarında dik falezler görülürken, yarımadayı anakaraya bağlayan berzah (boyun) kesiminde alçak kumsalların bulunması neyi gösterir?', 'Aynı yarımada üzerinde hem dalga aşındırma hem de dalga biriktirme koşullarının yerel derinliğe göre değiştiğini', ['Kuzey kıyılarda gelgitin güçlü, güney kıyılarda gelgitin tamamen etkisiz olduğunu', 'Boztepe kütlesinin tamamının akarsu alüvyonlarından oluştuğunu', 'Kuzeyde buzul aşındırmasının, güneyde rüzgar biriktirmesinin hakim olduğunu'], 'Eski adanın açık denize bakan dik kıyılarında falezler gelişirken, ada ile kara arasındaki sığ ve korunaklı kesimde kıyı oku birikerek tomboloyu oluşturmuştur.'),
  ('Taban morenleri ile cephe morenlerinin arazi üzerindeki görünümü karşılaştırıldığında aşağıdakilerden hangisi doğrudur?', 'Taban morenleri geniş ve dalgalı örtüler oluştururken, cephe morenleri buzul diline paralel kavisli sırtlar oluşturur', ['Taban morenleri sarp kayalık kuleler, cephe morenleri derin kanyonlar oluşturur', 'Taban morenleri yalnızca kıyılarda, cephe morenleri yalnızca çöllerde görülür', 'Taban morenleri tek boy kumdan, cephe morenleri saf kireçtaşından oluşur'], 'Buzulun altında ezilip yayılan malzeme taban moreni örtüsünü, buzul ucunda biriken yığınlar ise yay şekilli cephe moreni sırtlarını meydana getirir.'),
  ('Kaçkar Dağları\'na tırmanan bir dağcı grubu sırasıyla U profilli vadi, hörgüçkaya ve en üstte küçük bir buzul gölü gözlemlemiştir. En üstte gördükleri göl hangi çukurlukta yer alır?', 'Sirk çanağı', ['Obruk çukuru', 'Maar çukuru', 'Lagün çanağı'], 'Vadi buzullarının beslenme bölgesini oluşturan en üstteki koltuk şekilli oyuklar sirk çanaklarıdır ve erime sonrası sirk göllerine dönüşür.'),
  ('Bir kıyı okunun koy ağzını tamamen kapatmayıp dar bir boğaz bırakmasının temel nedeni aşağıdakilerden hangisi olabilir?', 'Koya dökülen akarsu akımının veya kıyı-lagün arası su alışverişinin ağzı açık tutması', ['Deniz suyunun donarak kum taşınmasını yıl boyu engellemesi', 'Kıyıdaki kayaçların bazalt ve granit gibi çok sert kütlelerden oluşması', 'Koy içindeki su derinliğinin binlerce metreyi bulması'], 'Lagün içindeki fazla suyun denize boşalması veya zayıf akıntı giriş-çıkışı kıyı kordonu üzerinde dar bir gideğen (boğaz) kalmasını sağlar.'),
  ('Buzulların aşındırma yaparken kayaları hem çizip cilalaması hem de iri bloklar halinde sökmesi hangi iki mekanizmayla gerçekleşir?', 'Törpüleme (abrazyon) ve koparma', ['Hidrolik vuruş ve kimyasal erime', 'Deflasyon ve korrazyon', 'Tuz çatlatması ve biyolojik ayrışma'], 'Buzul içindeki taşlar zemini zımpara gibi çizerken (abrazyon), donma-çözülme ile çatlayan ana kayadan bloklar sökülüp alınır (koparma).'),
  ('Türkiye\'de Beydağları, Bolkar Dağları, Aladağlar ve Mercan (Munzur) Dağları\'nın ortak jeomorfolojik özelliği aşağıdakilerden hangisidir?', 'Zirve kuşaklarında Kuaterner buzullaşmasına ait sirk ve moren izleri taşımaları', ['Kıyı çizgisine paralel uzanan aktif volkan konileri olmaları', 'Tamamının birinci jeolojik zamanda oluşmuş masif araziler olması', 'Eteklerinde geniş sander düzlükleri ve drumlin tarlaları bulunması'], 'Toros kuşağı ve Doğu Anadolu\'daki bu yüksek dağlar, yükseltileri 3000 metreyi aştığı için buzul aşınım ve birikim şekilleri barındırır.'),
  ('Kıyı çizgisinde bir mendirek veya dalgakıran inşa edildiğinde yapının bir tarafında kum birikimi hızlanırken diğer tarafında kıyı gerilemesi görülmesi neyle açıklanır?', 'Kıyı boyu akıntısının taşıdığı sediment dengesinin insan müdahalesiyle kesintiye uğramasıyla', ['Deniz tabanındaki fay hatlarının mühendislik yapıları nedeniyle harekete geçmesiyle', 'Mendirek çevresinde deniz suyu sıcaklığının ve buharlaşmanın artmasıyla', 'Gelgit genliğinin mendireğin bulunduğu koyda iki katına çıkmasıyla'], 'Kıyı boyu akıntısı engellendiğinde kumlar engelin önünde birikir; kum beslemesi kesilen diğer tarafta ise dalgalar kıyıyı aşındırır.'),
  ('Sander düzlüklerinin buzul cephesinden uzaklaştıkça tortul boyutunda nasıl bir değişim göstermesi beklenir?', 'İri çakıllardan ince kum ve mile doğru küçülmesi', ['İnce kilden dev kaya bloklarına doğru büyümesi', 'Mesafeden bağımsız olarak her yerde aynı boyutta kalması', 'Yalnızca köşeli blokların en uzak noktaya taşınması'], 'Erime sularının taşıma gücü buzul cephesinden uzaklaştıkça ve eğim azaldıkça düştüğü için önce iri çakıllar, uzakta ince kumlar birikir.'),
  ('Ria tipi kıyılar ile fiyort tipi kıyıların oluşum süreçlerindeki ortak nokta ve temel fark aşağıdakilerden hangisinde doğru verilmiştir?', 'Her ikisi de vadilerin deniz altında kalmasıyla oluşur; ria akarsu vadisi, fiyort ise buzul vadisi kökenlidir', ['Her ikisi de gelgit aşındırmasıyla oluşur; ria sıcak denizlerde, fiyort iç denizlerde görülür', 'Her ikisi de kıyı biriktirmesiyle oluşur; ria kumullardan, fiyort morenlerden meydana gelir', 'Her ikisi de volkanik çökmeyle oluşur; ria kraterlerde, fiyort kalderalarda gelişir'], 'Deniz seviyesinin yükselmesi (transgresyon) ortak süreçtir ancak boğulan vadi ria tipinde V profilli akarsu vadisi, fiyortta U profilli buzul vadisidir.'),
  ('Türkiye kıyılarında Rize-Trabzon arası ile İzmir-Aydın arası karşılaştırıldığında aşağıdakilerden hangisi İzmir-Aydın kıyıları için söylenemez?', 'Kıta sahanlığı daha dardır ve falezler tüm kıyı boyunca kesintisiz uzanır', ['Doğal liman, koy ve körfez sayısı daha fazladır', 'Kıyıdaki limanların iç kesimlerle olan art bölgesi (hinterlandı) daha geniştir', 'Akarsuların ağız kesimlerinde delta ovalarının oluşumu daha kolaydır'], 'İzmir-Aydın kıyıları enine kıyı tipindedir; kıta sahanlığı geniştir, kesintisiz falezler yerine koylar ve deltalar yaygındır.'),
  ('Haliçli kıyılarda büyük tonajlı okyanus gemilerinin nehir ağızlarından onlarca kilometre içerideki limanlara kadar girebilmesini sağlayan doğal süreç nedir?', 'Yüksek gelgit kabarmasıyla su derinliğinin artması ve gelgit akıntılarının ağızdaki alüvyonları temizlemesi', ['Akarsuların yatak eğiminin çok fazla olması ve şelaleler oluşturması', 'Nehir ağızlarının kıyı kordonlarıyla kapanarak durgun göllere dönüşmesi', 'Kış aylarında nehir sularının donarak buz kırıcı gemilere yol açması'], 'Gelgit akıntıları akarsu ağzında alüvyon birikmesini (deltayı) önler ve kabarma sırasında derinliği artırarak iç limanlara deniz ulaşımı sağlar.'),
  ('Bir akarsu ağzında aynı anda hem gelişmiş bir delta ovasının hem de derin bir halicin (estuar) bulunamamasının nedeni aşağıdakilerden hangisidir?', 'Haliç oluşturan güçlü gelgit akıntılarının delta oluşturacak alüvyonları açık denize süpürmesi', ['Deltaların yalnız soğuk kuşakta, haliçlerin yalnız ekvatoral kuşakta oluşması', 'Akarsuların haliçli kıyılara hiç alüvyon taşıyamaması', 'Delta kıyılarında deniz suyunun tatlı, haliçlerde aşırı tuzlu olması'], 'Delta ve haliç birbirine zıt koşulların ürünüdür; gelgit güçlüyse alüvyon birikemez ve haliç oluşur, gelgit zayıfsa alüvyon birikir ve delta oluşur.'),
  ('Dalmaçya kıyı tipinde kıyı önündeki adaların uzanış doğrultusu ile enine kıyı tipindeki adaların uzanış doğrultusu nasıl bir fark gösterir?', 'Dalmaçya tipinde adalar kıyı çizgisine paralel dizilirken, enine kıyıda uzantılar kıyıya dik doğrultudadır', ['Dalmaçya tipinde adalar çember şeklinde dizilirken, enine kıyıda rastgele dağılır', 'Dalmaçya tipindeki adalar tamamen kumdan, enine kıyıdaki adalar mercandan oluşur', 'Her iki kıyı tipinde de adalar kıyı çizgisine paralel uzanan moren sırtlarıdır'], 'Dalmaçya tipinde kıyıya paralel kıvrım dağları arasındaki senklinaller su altında kaldığından antiklinaller kıyıya paralel uzun adalar dizisi oluşturur.'),
  ('Karadeniz kıyısındaki Sinop Limanı doğal bir liman olmasına rağmen ekonomik gelişmişliğinin İzmir veya Mersin limanlarının gerisinde kalması boyuna kıyıların hangi sonucuyla açıklanır?', 'Kıyı gerisinde uzanan Küre Dağları nedeniyle iç kesimlerle ulaşımın zor ve hinterlandı dar olması', ['Liman sularının yılın yarısında donarak gemi trafiğine kapanması', 'Kıyı önündeki gelgit çekilmeleri nedeniyle gemilerin karaya oturması', 'Sinop çevresinde yıllık yağış miktarının çok düşük olması'], 'Boyuna kıyılarda dağlar kıyı gerisinde engel oluşturduğu için doğal liman bulunsa bile art bölge (hinterland) bağlantısı zayıf kalabilir.'),
  ('Şili\'nin güney kıyıları, Alaska kıyıları, Yeni Zelanda\'nın güneybatısı ve Norveç kıyılarının ortak jeomorfolojik özelliği aşağıdakilerden hangisidir?', 'Yüksek enlemlerdeki buzul vadilerinin deniz altında kalmasıyla oluşan fiyortlu kıyılar olmaları', ['Sıcak okyanus akıntıları sayesinde gelişmiş mercan resiflerine sahip olmaları', 'Kıyı boyunca geniş çöl kumullarının doğrudan okyanusa kavuşması', 'Dünyanın en büyük delta ovalarının bu kıyılarda yer alması'], 'Hem kuzey hem güney yarımkürenin yüksek orta ve kutup altı enlemlerindeki dağlık batı kıyıları tipik fiyort kıyılarıdır.'),
  ('Watt kıyılarının bulunduğu Kuzey Denizi sahillerinde gelgit çekilmesi (cezir) ile gelgit yükselmesi (med) arasındaki saatlerde kıyı görünümü nasıl değişir?', 'Su çekildiğinde kilometrelerce genişlikte çamurlu-kumlu deniz tabanı açığa çıkar, su yükseldiğinde tekrar denizle örtülür', ['Su çekildiğinde yüksek falezler ortaya çıkar, su yükseldiğinde şelaleler oluşur', 'Kıyı çizgisi yıl boyunca sabit kalır, yalnızca suyun rengi değişir', 'Su çekildiğinde mercan kayalıkları kurur, su yükseldiğinde lagünler tatlılaşır'], 'Çok az eğimli kıyı düzlüklerinde birkaç metrelik gelgit seviye farkı bile kıyı çizgisinin kilometrelerce ileri-geri oynamasına (watt düzlüğü) neden olur.'),
  ('İstanbul ve Çanakkale boğazlarının kıvrımlı uzanışı, karşılıklı girinti-çıkıntılarının uyumu ve tabanlarında eski menderes oluklarının bulunması neyin kanıtıdır?', 'Dördüncü jeolojik zamanda deniz istilasına uğramış eski akarsu vadileri (ria kıyısı) olduklarının', ['Büyük bir örtü buzulunun Marmara\'yı yararak Karadeniz\'e aktığının', 'Şiddetli gelgit akıntılarının karayı oyarak huni şekilli kanal açtığının', 'İki kıta arasındaki volkanik patlamalarla çöküntü çukuru oluştuğunun'], 'Boğazlarımız Kuaterner\'de deniz seviyesinin yükselmesiyle sular altında kalmış eski akarsu vadileridir.'),
  ('Ege kıyılarında Büyük Menderes ve Küçük Menderes nehirlerinin hızla delta ilerlemesi yaparak antik liman kentlerini (Milet, Efes) kıyıdan içeride bırakması enine kıyıların hangi özelliğiyle desteklenmiştir?', 'Graben oluklarının önündeki koyların sığ olması ve kıta sahanlığının genişliğiyle', ['Ege Denizi\'nde dalga aşındırmasının falezleri hızla geriletmesiyle', 'Kıyı boyunca uzanan dağların akarsuların denize ulaşmasını engellemesiyle', 'Ege kıyılarında gelgit genliğinin okyanus seviyesinde olmasıyla'], 'Enine kıyılardaki korunaklı ve sığ körfezler, grabenlerden bol alüvyon taşıyan akarsuların hızla dolgu yaparak kıyıyı ilerletmesini kolaylaştırmıştır.'),
  ('Büyükçekmece ve Küçükçekmece lagünlerinin bulunduğu kıyı kesimi, köken olarak daha önce hangi kıyı tipinin özellikleri üzerine gelişmiştir?', 'Boğulmuş akarsu vadisi ağızlarının (ria/limanlı kıyı) kıyı kordonlarıyla kapanması üzerine', ['Eski buzul vadilerinin (fiyort) cephe morenleriyle tıkanması üzerine', 'Mercan halkalarının (atol) su yüzüne çıkarak koyu çevrelemesi üzerine', 'Yüksek falezlerin çökerek koy ağzını kaya bloklarıyla kapatması üzerine'], 'Çekmece gölleri önce eski vadi ağızlarının deniz altında kalmasıyla koy haline gelmiş, ardından dalgaların kıyı kordonu örmesiyle lagüne dönüşmüştür.'),
  ('Bir fiziki haritada kıyı çizgisinden itibaren 200 metre derinlik izobatı (eş derinlik eğrisi) kıyıya çok yakın geçiyorsa bu kıyı hakkında hangi çıkarım doğrudur?', 'Kıta sahanlığı dardır, kıyı aniden derinleşir ve boyuna kıyı özelliği taşıma olasılığı yüksektir', ['Kıta sahanlığı çok geniştir, watt ve lagün oluşumu için idealdir', 'Akarsuların getirdiği alüvyonlarla kısa sürede geniş deltalar oluşur', 'Kıyı önünde çok sayıda tombolo ve kum adası gelişmiştir'], '200 m izobatı kıta sahanlığı sınırını gösterir; kıyıya çok yakın geçmesi şelfin dar ve denizin hemen derinleştiğini ifade eder.'),
  ('Fiyortların denizle birleştiği ağız kesimlerinde genellikle su derinliğinin iç kısımlara göre daha az olduğu bir eşik (fiyort eşiği) bulunmasının nedeni nedir?', 'Buzulun denize kavuşurken incelip yüzmeye başlamasıyla aşındırma gücünün azalması ve cephe moreni bırakması', ['Okyanus dalgalarının fiyort ağzına mercan resifleri inşa etmesi', 'Akarsuların fiyort ağzında geniş delta ovaları oluşturması', 'Kıyıdaki rüzgarların çöl kumlarını fiyort girişine yığması'], 'Vadi buzulu iç kesimde kalın olduğu için tabanı çok derin kazarken, denize ulaştığı ağızda incelir ve aşındırması zayıflayarak sığ bir kaya/moren eşiği bırakır.'),
  ('Skyer tipi kıyılar ile Dalmaçya tipi kıyıların her ikisinde de kıyı önünde çok sayıda ada bulunmasına karşın bu adaları birbirinden ayıran temel özellik nedir?', 'Dalmaçya adaları yapısal kıvrım sırtları halinde paralel ve uzun iken, skyer adaları düzensiz dağılmış basık hörgüçkaya ve moren tepeleridir', ['Dalmaçya adaları yüksek enlemlerde, skyer adaları yalnızca ekvator çevresinde görülür', 'Dalmaçya adaları volkanik tüflerden, skyer adaları mercan kalkerlerinden oluşur', 'Dalmaçya adaları gelgit çekildiğinde karaya bağlanır, skyer adaları sürekli su altındadır'], 'Dalmaçya kıyısı orojenik kıvrım yapısının, skyer kıyısı ise düzensiz buzul aşınım-birikim yüzeyinin deniz altında kalmasıyla oluşur.'),
  ('Kuzeybatı Fransa\'daki ünlü Mont-Saint-Michel adasının günün belirli saatlerinde yaya olarak ulaşılabilen bir kara parçasına, belirli saatlerinde ise sularla çevrili bir adaya dönüşmesi hangi kıyı tipinin sonucudur?', 'Watt kıyısı', ['Dalmaçya kıyısı', 'Fiyort kıyısı', 'Ria kıyısı'], 'Manş Denizi kıyılarında gelgit genliği 10 metreyi aştığı için sular çekildiğinde geniş watt düzlüğü açığa çıkarak adaya geçit verir.'),
  ('Karadeniz\'in doğu kıyılarında dağlardan inen çok sayıda gür akarsu bulunmasına rağmen Çarşamba ovasının doğusunda büyük bir delta gelişememesinin nedenleri nelerdir?', 'Kıta sahanlığının çok dar olması, denizin hemen derinleşmesi ve güçlü kıyı akıntıları', ['Akarsuların havzalarında aşındırma yapamaması ve berrak akması', 'Doğu Karadeniz\'de gelgit genliğinin 8 metreye ulaşması', 'Bölgedeki tüm akarsuların karstik düdenlerle yeraltına sızması'], 'Boyuna kıyı yapısı nedeniyle Doğu Karadeniz\'de şelf çok dardır; taşınan alüvyonlar dik denizaltı yamaçlarından derine kayar ve dalgalarla dağıtılır.'),
  ('Aşağıdaki kıyı tipi çiftlerinden hangisinin oluşumunda iklim koşullarının (sıcaklık ve buzullaşma veya tropikal su sıcaklığı) doğrudan belirleyici etkisi vardır?', 'Fiyortlu kıyı ve Mercanlı kıyı', ['Boyuna kıyı ve Enine kıyı', 'Ria kıyı ve Dalmaçya kıyı', 'Haliçli kıyı ve Boyuna kıyı'], 'Fiyort kıyıları soğuk iklim ve buzullaşmaya, mercanlı kıyılar ise sıcak tropikal deniz suyuna bağlı olduğu için iklime doğrudan bağımlıdır.'),
  ('Hollanda kıyılarında "polder" adı verilen denizden kazanılmış tarım arazilerinin oluşturulabilmesini kolaylaştıran doğal kıyı özelliği aşağıdakilerden hangisidir?', 'Sığ watt kıyıları ile bunların önündeki kıyı adacıkları ve kumul dizilerinin set yapımına uygun olması', ['Kıyıda yüzlerce metre yüksekliğinde granit falezlerin bulunması', 'Derin fiyort vadilerinin tatlı su göllerine dönüştürülmesi', 'Mercan resiflerinin dalgaları tamamen durdurması'], 'Sığ deniz tabanı (watt) ve kıyı kordonu adaları (Frizya adaları) arasına bentler çekilip su pompalanarak alçak kıyı düzlükleri tarıma açılmıştır.'),
  ('Aşağıdaki kıyı tiplerinden hangisinin şekillenmesinde iç kuvvetlerin oluşturduğu dağ uzanış doğrultusu birincil derecede belirleyicidir?', 'Boyuna, Enine ve Dalmaçya kıyılar', ['Haliçli ve Watt kıyılar', 'Mercanlı ve Atol kıyılar', 'Fiyortlu ve Skyer kıyılar'], 'Dağların kıyıya paralel (boyuna, dalmaçya) veya dik (enine) uzanması doğrudan orojenik ve tektonik yapıyla ilgilidir.'),
  ('Akdeniz\'de İskenderun Körfezi ile Çukurova kıyılarında kıta sahanlığının Antalya-Gazipaşa kıyılarına göre çok daha geniş olması neyle açıklanır?', 'Dağ sırasının kıyıdan uzaklaşması, çöküntü alanı varlığı ve Seyhan-Ceyhan nehirlerinin alüvyal dolgusuyla', ['İskenderun Körfezi\'nde okyanus tipi gelgit akıntılarının etkili olmasıyla', 'Gazipaşa kıyılarında buzul aşındırmasının şelfi daraltmasıyla', 'Çukurova açıklarında aktif volkanik adaların yükselmesiyle'], 'Adana-İskenderun kesiminde Toroslar içeride kalır ve büyük nehirlerin biriktirdiği Çukurova deltası kıyıyı sığlaştırıp şelfi genişletir.'),
  ('Haliçli kıyıların bulunduğu Batı Avrupa okyanus sahillerinde limanların hızla gelişip dünya ticaretinde öne çıkmasında hangi iki faktör birlikte rol oynamıştır?', 'Gelgitin koruduğu derin nehir ağzı limanları ve gerideki düz-ulaşılabilir geniş hinterland', ['Kıyı boyunca uzanan sarp sıradağlar ve kısa boylu sel rejimli akarsular', 'Lagünlerin önünü kapatan kıyı okları ve sığ abrazyon platformları', 'Kışın donan fiyort kanalları ve yüksek dağ geçitleri'], 'Batı Avrupa\'da hem haliçler büyük gemilere doğal barınak sağlamış hem de uysal rejimli nehirler ve düz ovalar iç kesimlerle ucuz ulaşım sunmuştur.'),
  ('Bir gözlemci Türkiye kıyılarını gezdiğinde Sinop\'ta tombolo, Büyükçekmece\'de lagün, Kaş\'ta Dalmaçya kıyısı ve Antalya merkezde falez görmüştür. Gözlemcinin Türkiye kıyılarında doğal olarak göremeyeceği ikili hangisidir?', 'Fiyort ve Watt', ['Ria ve Enine kıyı', 'Boyuna kıyı ve Tombolo', 'Lagün ve Falez'], 'Türkiye\'de orta kuşak konumu nedeniyle fiyort, iç deniz özelliği (zayıf gelgit) nedeniyle watt kıyıları görülmez.'),
  ('Limanlı kıyı tipinde (Karadeniz\'in kuzeyi) başlangıçta deniz istilasıyla oluşan koyların zamanla lagünleşmesinin temel nedeni nedir?', 'Gelgitin zayıf olduğu sığ denizde dalga ve kıyı akıntılarının vadi ağızlarına kıyı kordonları örmesi', ['Kuzeyden inen güncel buzulların koy önlerine moren yığması', 'Okyanus akıntılarının koy içindeki suları hızla boşaltması', 'Tektonik yükselmeyle tüm koy tabanlarının platoya dönüşmesi'], 'Azak ve Kuzey Karadeniz kıyılarında geniş akarsu vadileri (limanlar) sular altında kaldıktan sonra sığlık ve zayıf gelgit sayesinde kıyı oklarıyla kapanmıştır.'),
  ('Örtü buzullarından koparak okyanus ve denizlerde akıntılarla sürüklenen dev yüzen buz kütlelerine ne ad verilir?', 'Aysberg', ['Drumlin', 'Hörgüçkaya', 'Moren'], 'Grönland ve Antarktika kıyılarında buzul dillerinden kopup denize düşen yüzen buz kütleleri aysberg olarak adlandırılır.'),
  ('Ağrı Dağı\'nın zirvesinde vadi buzulundan ziyade Türkiye\'nin en büyük takke (doruk) buzulunun gelişmiş olmasının jeomorfolojik nedeni nedir?', 'Volkanik koni yapısının zirvede geniş ve kubbemsi bir yüzey oluşturması', ['Dağın deniz seviyesine çok yakın bir ovada yer alması', 'Ağrı Dağı\'nın kireçtaşı tabakalarının çökmesiyle oluşması', 'Zirvede yıl boyunca sıcak su kaynaklarının akması'], '5137 metrelik Ağrı Dağı düzgün bir stratovolkan konisi olduğundan zirve kesiminde buz kütlesi kubbe biçimli takke buzulu olarak tutunur.'),
  ('Bir bölgede buzul aşınım ve birikim şekillerinin kalıcı kar sınırının çok altındaki yükseltilerde (örneğin 2200 metrede) fosil olarak görülmesi neyi kanıtlar?', 'Geçmiş jeolojik dönemlerde iklimin bugünkünden daha soğuk olduğu buzul çağlarının yaşandığını', ['Dağın son birkaç yılda bin metre alçaldığını', 'Rüzgarların morenleri zirveden ovaya indirdiğini', 'Kalıcı kar sınırının geçmişte bugünkünden çok daha yüksek olduğunu'], 'Güncel kalıcı kar sınırı Türkiye\'de 3200-3700 m iken 2200 m\'de sirk ve moren bulunması, Kuaterner\'deki soğuk dönemlerin (Pleistocene) kanıtıdır.'),
  ('Kıyı oklarının gelişme yönünü belirleyen en temel etken aşağıdakilerden hangisidir?', 'Hakim rüzgarların yönlendirdiği kıyı boyu akıntılarının yönü', ['Deniz tabanındaki kayaçların jeolojik yaşı', 'Kıyıdaki bitki örtüsünün gürlüğü ve tür çeşitliliği', 'Yeraltı sularının denize boşalma sıcaklığı'], 'Dalgaların kıyıya eğik çarpmasıyla oluşan kıyı boyu akıntısı, kumları akış yönünde taşıyarak kıyı okunun uzama yönünü tayin eder.'),
  ('Bir koyun önünü kapatan kıyı kordonu üzerinde zamanla rüzgar etkisiyle kıyı kumullarının gelişmesi hangi süreç dizisini gösterir?', 'Dalga biriktirmesiyle su üstüne çıkan kumların kuruyup rüzgar biriktirmesiyle yeniden şekillendiğini', ['Buzul biriktirmesinin yerini doğrudan karstik erimeye bıraktığını', 'Gelgit aşındırmasının falezleri kumula dönüştürdüğünü', 'Akarsu aşındırmasının kıyı kordonunu kanyona çevirdiğini'], 'Dalgaların oluşturduğu plaj ve kordonlardaki kumlar kuruduğunda denizden esen rüzgarlarla taşınarak kıyı kumullarını oluşturur.'),
  ('Aşağıdaki Türkiye dağlarından hangisinde Kuaterner buzullaşmasına ait sirk, tekne vadi veya moren izlerine rastlanması beklenmez?', 'Karacadağ (Şanlıurfa)', ['Sat Dağları (Hakkari)', 'Verçenik Dağı (Rize)', 'Dedegöl Dağları (Isparta)'], 'Güneydoğu Anadolu\'daki kalkan volkanı Karacadağ yaklaşık 1957 m yükseltisi ve güneydeki sıcak konumu nedeniyle buzullaşma sınırına ulaşamamıştır.'),
  ('Falezli bir kıyıda kayaç tabakalarının denize doğru eğimli olması ile karaya doğru eğimli olması falez gerileme hızını nasıl etkiler?', 'Denize doğru eğimli tabakalarda kütle kayması kolaylaştığı için falez daha hızlı çöker ve geriler', ['Denize doğru eğimli tabakalarda falez hiç aşınmaz ve sabit kalır', 'Tabaka eğiminin falez duraylılığı üzerinde hiçbir etkisi yoktur', 'Karaya doğru eğimli tabakalarda heyelan riski en yüksek düzeye çıkar'], 'Tabakalar denize doğru eğimli olduğunda dalga alt kısmı oyunca üstteki tabakalar eğim yönünde kolayca kayıp denize çöker.'),
  ('Marmara Denizi\'nde hem ria kıyı tipinin (Boğazlar), hem tombolonun (Kapıdağ) hem de lagünlerin (Büyükçekmece, Küçükçekmece) görülmesi neyi ifade eder?', 'Farklı tektonik geçmiş ve yerel derinlik koşulları sayesinde kıyı şekli çeşitliliğinin fazla olduğunu', ['Marmara Denizi\'nde gelgit genliğinin okyanuslardan daha yüksek olduğunu', 'Marmara kıyılarının tamamının tek bir kıyı tipinden oluştuğunu', 'Bölgede yalnızca rüzgar ve buzul dış kuvvetlerinin etkili olduğunu'], 'Kıyı derinliği, eski vadi yapıları, adaların konumu ve zayıf gelgit Marmara\'da zengin bir kıyı jeomorfolojisi oluşturmuştur.'),
  ('Bir harita üzerinde İskenderiye (Nil Deltası) kıyılarında Meryut ve Menzale gibi geniş lagünlerin delta cephesinde dizildiği görülüyorsa burada hangi koşul geçerlidir?', 'Gelgit genliği düşüktür ve kıyı boyu akıntıları delta ağızları arasında kıyı kordonları örmüştür', ['Nil Nehri denize hiç alüvyon taşımamaktadır', 'Akdeniz\'in bu kesiminde dağlar kıyıdan hemen 3000 metre yükselmektedir', 'Bölgede fiyort eşikleri koy önlerini kapatmıştır'], 'Nil Deltası\'nın sığ cephesinde Akdeniz\'in doğu yönlü kıyı akıntıları kum kordonları oluşturarak tipik delta lagünlerini meydana getirmiştir.'),
  ('Boyuna kıyıların görüldüğü Karadeniz\'de liman yapımında genellikle yapay dalgakıranlara (mendirek) ihtiyaç duyulurken, Ege kıyılarında buna daha az gerek duyulmasının sebebi nedir?', 'Karadeniz\'de kıyının düz ve korunaklı koyların az olması, Ege\'de ise girintili-çıkıntılı doğal koyların yaygınlığı', ['Karadeniz\'de su tuzluluğunun gemilere zarar vermesi', 'Ege Denizi\'nde yıl boyunca hiç rüzgar ve dalga oluşmaması', 'Karadeniz kıyılarının tamamının sığ watt düzlükleriyle kaplı olması'], 'Boyuna kıyılarda kıyı çizgisi sade olduğundan Sinop dışında doğal kapalı liman azdır; açık deniz dalgalarına karşı mendirek yapılır.'),
  ('Kutup bölgelerinde deniz suyunun aşırı soğumasıyla deniz yüzeyinin donarak oluşturduğu birkaç metre kalınlığındaki yüzen buz örtüsüne ne ad verilir?', 'Bankiz', ['Moren', 'Sirk', 'Sander'], 'Deniz suyunun donmasıyla oluşan tabaka halindeki deniz buzuna bankiz denir; kara buzullarından kopan aysbergden farklıdır.'),
  ('Aşağıdaki eşleştirmelerden hangisinde yer şekli ile Türkiye\'deki örneği yanlış verilmiştir?', 'Haliçli kıyı - İzmir Körfezi', ['Tombolo - Kapıdağ Yarımadası', 'Lagün - Terkos Gölü', 'Dalmaçya kıyı - Finike-Kaş kıyıları'], 'İzmir Körfezi haliçli kıyı değil, çöküntü grabeninin deniz altında kalmasıyla oluşan enine kıyı körfezidir.'),
  ('Bir vadi buzulunun yamaçlardan düşen kaya parçalarıyla beslenmesi sonucunda buzul yüzeyinin kenarlarında koyu renkli iki şerit görülmesi hangi şeklin oluşmakta olduğunu gösterir?', 'Yan morenlerin', ['Hörgüçkayaların', 'Sirk göllerinin', 'Abrazyon platformunun'], 'Donma-çözülme ile vadi yamaçlarından kopup buzulun iki kenarına düşen taş ve enkaz şeritleri yan morenleri oluşturur.'),
];
